import struct, sys
M=0xffffffff
def rotr(x,n): return ((x>>n)|(x<<(32-n)))&M
def rotl(x,n): return ((x<<n)|(x>>(32-n)))&M
class HC:
    def __init__(self, seed_bytes):
        seed=list(struct.unpack('<8I', seed_bytes))
        f1=lambda x: rotr(x,7)^rotr(x,18)^(x>>3)
        f2=lambda x: rotr(x,17)^rotr(x,19)^(x>>10)
        t=[0]*1024
        t[0:4]=seed[0:4]; t[4:8]=seed[0:4]; t[8:12]=seed[4:8]; t[12:16]=seed[4:8]
        for i in range(16,272):
            t[i]=(f2(t[i-2])+t[i-7]+f1(t[i-15])+t[i-16]+i)&M
        t[0:16]=t[256:272]
        for i in range(16,1024):
            t[i]=(f2(t[i-2])+t[i-7]+f1(t[i-15])+t[i-16]+256+i)&M
        self.t=t; self.c=0
        for _ in range(1024):
            j=self.c%512
            if self.c<512:
                self.t[j]=self.step_p(j)
            else:
                self.t[512+j]=self.step_q(j)
            self.c+=1
        self.c=0
        self.results=[0]*16; self.index=16
    def step_p(self,j):
        p=self.t
        t0=rotr(p[(j+1)%512],23); t1=rotr(p[(j-3)%512],10); t2=rotr(p[(j-10)%512],8)
        p[j]=(p[j]+t2+(t0^t1))&M
        x=p[(j-12)%512]
        h=(p[512+(x&0xff)]+p[512+256+((x>>16)&0xff)])&M
        return h^p[j]
    def step_q(self,j):
        p=self.t
        q=lambda k: p[512+(k%512)]
        t0=rotl(q(j+1),23); t1=rotl(q(j-3),10); t2=rotl(q(j-10),8)
        p[512+j]=(p[512+j]+t2+(t0^t1))&M
        x=q(j-12)
        h=(p[(x&0xff)]+p[256+((x>>16)&0xff)])&M
        return h^p[512+j]
    def gen(self):
        r=[]
        for _ in range(16):
            j=self.c%512
            if (self.c & 512)==0: r.append(self.step_p(j))
            else: r.append(self.step_q(j))
            self.c=(self.c+1)%(1<<32)
        self.results=r
    def next_u32(self):
        if self.index>=16:
            self.gen(); self.index=0
        v=self.results[self.index]; self.index+=1; return v
    def next_u64(self):
        i=self.index
        if i<15:
            self.index+=2
            return self.results[i] | (self.results[i+1]<<32)
        elif i>=16:
            self.gen(); self.index=2
            return self.results[0] | (self.results[1]<<32)
        else:
            x=self.results[15]; self.gen(); self.index=1
            return x | (self.results[0]<<32)
def gen_range(rng, low, high):
    rngv=(high-low)
    lz=64-rngv.bit_length()
    zone=((rngv<<lz)&((1<<64)-1))-1
    zone&=(1<<64)-1
    while True:
        v=rng.next_u64()
        m=v*rngv
        hi=m>>64; lo=m&((1<<64)-1)
        if lo<=zone: return low+hi
def sample(n, k, seed):
    rng=HC(struct.pack('<Q',seed)+b'\0'*24)
    res=list(range(min(k,n)))
    for i in range(k,n):
        r=gen_range(rng,0,i+1)
        if r<k: res[r]=i
    return res
if __name__=='__main__':
    for s in [0,1,2,42]: print(sample(100,5,s))
