//! A small CSV reader/writer modelled on the semantics expected by xsv.

use std::fmt;
use std::io::{self, Read, Seek, SeekFrom, Write};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Position {
    pub byte: u64,
    pub line: u64,
    pub record: u64,
}

impl Position {
    pub fn new() -> Position {
        Position { byte: 0, line: 1, record: 0 }
    }
}

#[derive(Clone, Debug, Default)]
pub struct ByteRecord {
    data: Vec<u8>,
    ends: Vec<usize>,
    pos: Option<Position>,
}

impl ByteRecord {
    pub fn new() -> ByteRecord {
        ByteRecord::default()
    }

    pub fn from_fields<'a, I: IntoIterator<Item = &'a [u8]>>(it: I) -> ByteRecord {
        let mut r = ByteRecord::new();
        for f in it {
            r.push_field(f);
        }
        r
    }

    pub fn len(&self) -> usize {
        self.ends.len()
    }

    pub fn is_empty(&self) -> bool {
        self.ends.is_empty()
    }

    pub fn clear(&mut self) {
        self.data.clear();
        self.ends.clear();
    }

    pub fn as_slice(&self) -> &[u8] {
        &self.data
    }

    pub fn position(&self) -> Option<Position> {
        self.pos
    }

    pub fn set_position(&mut self, p: Option<Position>) {
        self.pos = p;
    }

    pub fn get(&self, i: usize) -> Option<&[u8]> {
        if i >= self.ends.len() {
            return None;
        }
        let start = if i == 0 { 0 } else { self.ends[i - 1] };
        Some(&self.data[start..self.ends[i]])
    }

    pub fn push_field(&mut self, f: &[u8]) {
        self.data.extend_from_slice(f);
        self.ends.push(self.data.len());
    }

    pub fn truncate(&mut self, n: usize) {
        if n < self.ends.len() {
            self.ends.truncate(n);
            let end = if n == 0 { 0 } else { self.ends[n - 1] };
            self.data.truncate(end);
        }
    }

    pub fn extend_from(&mut self, other: &ByteRecord) {
        for f in other.iter() {
            self.push_field(f);
        }
    }

    pub fn iter(&self) -> RecordIter<'_> {
        RecordIter { rec: self, i: 0 }
    }

    fn push_byte(&mut self, b: u8) {
        self.data.push(b);
    }

    fn end_field(&mut self) {
        self.ends.push(self.data.len());
    }
}

impl std::ops::Index<usize> for ByteRecord {
    type Output = [u8];
    fn index(&self, i: usize) -> &[u8] {
        match self.get(i) {
            Some(f) => f,
            None => crate::util::fake_panic(
                "src/select.rs:362:22",
                "called `Option::unwrap()` on a `None` value",
            ),
        }
    }
}

pub struct RecordIter<'a> {
    rec: &'a ByteRecord,
    i: usize,
}

impl<'a> Iterator for RecordIter<'a> {
    type Item = &'a [u8];
    fn next(&mut self) -> Option<&'a [u8]> {
        let r = self.rec.get(self.i);
        if r.is_some() {
            self.i += 1;
        }
        r
    }
}

impl<'a> IntoIterator for &'a ByteRecord {
    type Item = &'a [u8];
    type IntoIter = RecordIter<'a>;
    fn into_iter(self) -> RecordIter<'a> {
        self.iter()
    }
}

#[derive(Debug)]
pub enum Error {
    Io(io::Error),
    UnequalLengths {
        pos: Option<Position>,
        expected_len: u64,
        len: u64,
    },
}

impl From<io::Error> for Error {
    fn from(e: io::Error) -> Error {
        Error::Io(e)
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            Error::Io(ref e) => e.fmt(f),
            Error::UnequalLengths { pos: None, expected_len, len } => write!(
                f,
                "CSV error: found record with {} fields, but the previous record has {} fields",
                len, expected_len
            ),
            Error::UnequalLengths { pos: Some(ref pos), expected_len, len } => write!(
                f,
                "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                pos.record, pos.line, pos.byte, len, expected_len
            ),
        }
    }
}

pub type Result<T> = std::result::Result<T, Error>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum St {
    StartRecord,
    EndRecord,
    StartField,
    InField,
    InQuotedField,
    InEscapedQuote,
    InDoubleEscapedQuote,
    InRecordTerm,
    Crlf,
    End,
}

#[derive(Clone, Copy, Debug)]
pub struct ReaderOptions {
    pub delimiter: u8,
    pub quote: u8,
    pub escape: Option<u8>,
    pub double_quote: bool,
    pub quoting: bool,
    pub has_headers: bool,
    pub flexible: bool,
}

#[derive(PartialEq, Eq, Clone, Copy)]
enum Eof {
    NotEof,
    Eof,
    IoError,
}

pub struct Reader<R> {
    rdr: R,
    buf: Vec<u8>,
    bpos: usize,
    blen: usize,
    opts: ReaderOptions,
    state: St,
    line: u64,
    has_read: bool,
    cur_pos: Position,
    eof: Eof,
    headers: Option<ByteRecord>,
    first: bool,
    seeked: bool,
    first_field_count: Option<u64>,
}

const BUF_SIZE: usize = 8 * (1 << 10);

impl<R: Read> Reader<R> {
    pub fn new(rdr: R, opts: ReaderOptions) -> Reader<R> {
        Reader {
            rdr,
            buf: vec![0; BUF_SIZE],
            bpos: 0,
            blen: 0,
            opts,
            state: St::StartRecord,
            line: 1,
            has_read: false,
            cur_pos: Position::new(),
            eof: Eof::NotEof,
            headers: None,
            first: false,
            seeked: false,
            first_field_count: None,
        }
    }

    pub fn has_headers(&self) -> bool {
        self.opts.has_headers
    }

    fn fill_buf(&mut self) -> io::Result<usize> {
        if self.bpos >= self.blen {
            loop {
                match self.rdr.read(&mut self.buf) {
                    Ok(n) => {
                        self.bpos = 0;
                        self.blen = n;
                        break;
                    }
                    Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                    Err(e) => return Err(e),
                }
            }
        }
        Ok(self.blen - self.bpos)
    }

    /// Reads one raw record from the underlying data. Returns false at EOF.
    fn read_core(&mut self, record: &mut ByteRecord) -> io::Result<bool> {
        let delim = self.opts.delimiter;
        let quote = self.opts.quote;
        let escape = self.opts.escape;
        let dq = self.opts.double_quote;
        let quoting = self.opts.quoting;
        let mut consumed: u64 = 0;
        if !self.has_read {
            let avail = match self.fill_buf() {
                Ok(n) => n,
                Err(e) => {
                    self.cur_pos.byte += consumed;
                    return Err(e);
                }
            };
            if avail >= 3 && &self.buf[self.bpos..self.bpos + 3] == b"\xef\xbb\xbf" {
                self.bpos += 3;
                consumed += 3;
            }
            self.has_read = true;
        }
        let result;
        'outer: loop {
            let avail = match self.fill_buf() {
                Ok(n) => n,
                Err(e) => {
                    self.cur_pos.byte += consumed;
                    self.cur_pos.line = self.line;
                    return Err(e);
                }
            };
            if avail == 0 {
                // EOF
                match self.state {
                    St::StartRecord | St::EndRecord | St::Crlf | St::End => {
                        self.state = St::End;
                        result = false;
                    }
                    _ => {
                        record.end_field();
                        self.state = St::EndRecord;
                        result = true;
                    }
                }
                break 'outer;
            }
            while self.bpos < self.blen {
                let b = self.buf[self.bpos];
                match self.state {
                    St::End => {
                        result = false;
                        break 'outer;
                    }
                    St::StartRecord => {
                        if b == b'\r' || b == b'\n' {
                            self.bpos += 1;
                            consumed += 1;
                            if b == b'\n' {
                                self.line += 1;
                            }
                        } else {
                            self.state = St::StartField;
                        }
                    }
                    St::EndRecord => {
                        self.state = St::StartRecord;
                    }
                    St::StartField => {
                        if quoting && b == quote {
                            self.bpos += 1;
                            consumed += 1;
                            self.state = St::InQuotedField;
                        } else if b == delim {
                            self.bpos += 1;
                            consumed += 1;
                            if b == b'\n' {
                                self.line += 1;
                            }
                            record.end_field();
                        } else if b == b'\r' || b == b'\n' {
                            self.state = St::InRecordTerm;
                        } else {
                            self.bpos += 1;
                            consumed += 1;
                            record.push_byte(b);
                            self.state = St::InField;
                        }
                    }
                    St::InField => {
                        if b == delim {
                            self.bpos += 1;
                            consumed += 1;
                            record.end_field();
                            self.state = St::StartField;
                        } else if b == b'\r' || b == b'\n' {
                            self.state = St::InRecordTerm;
                        } else {
                            self.bpos += 1;
                            consumed += 1;
                            record.push_byte(b);
                        }
                    }
                    St::InQuotedField => {
                        self.bpos += 1;
                        consumed += 1;
                        if b == b'\n' {
                            self.line += 1;
                        }
                        if quoting && b == quote {
                            self.state = St::InDoubleEscapedQuote;
                        } else if quoting && escape == Some(b) {
                            self.state = St::InEscapedQuote;
                        } else {
                            record.push_byte(b);
                        }
                    }
                    St::InEscapedQuote => {
                        self.bpos += 1;
                        consumed += 1;
                        if b == b'\n' {
                            self.line += 1;
                        }
                        record.push_byte(b);
                        self.state = St::InQuotedField;
                    }
                    St::InDoubleEscapedQuote => {
                        if quoting && dq && b == quote {
                            self.bpos += 1;
                            consumed += 1;
                            record.push_byte(b);
                            self.state = St::InQuotedField;
                        } else if b == delim {
                            self.bpos += 1;
                            consumed += 1;
                            record.end_field();
                            self.state = St::StartField;
                        } else if b == b'\r' || b == b'\n' {
                            self.state = St::InRecordTerm;
                        } else {
                            self.bpos += 1;
                            consumed += 1;
                            record.push_byte(b);
                            self.state = St::InField;
                        }
                    }
                    St::InRecordTerm => {
                        self.bpos += 1;
                        consumed += 1;
                        record.end_field();
                        if b == b'\r' {
                            self.state = St::Crlf;
                        } else {
                            self.line += 1;
                            self.state = St::EndRecord;
                        }
                        result = true;
                        break 'outer;
                    }
                    St::Crlf => {
                        if b == b'\n' {
                            self.bpos += 1;
                            consumed += 1;
                            self.line += 1;
                        }
                        self.state = St::StartRecord;
                    }
                }
            }
        }
        self.cur_pos.byte += consumed;
        self.cur_pos.line = self.line;
        Ok(result)
    }

    fn read_impl(&mut self, record: &mut ByteRecord) -> Result<bool> {
        record.clear();
        record.set_position(Some(self.cur_pos));
        if self.eof != Eof::NotEof {
            return Ok(false);
        }
        match self.read_core(record) {
            Err(e) => {
                self.eof = Eof::IoError;
                Err(Error::Io(e))
            }
            Ok(false) => {
                self.eof = Eof::Eof;
                Ok(false)
            }
