                                return Err(Error::UnequalLengths {
                                    pos: record.position(),
                                    expected_len: expected,
                                    len: record.len() as u64,
                                });
                            }
                        }
                    }
                }
                Ok(true)
            }
        }
    }

    pub fn byte_headers(&mut self) -> Result<ByteRecord> {
        if self.headers.is_none() {
            let mut record = ByteRecord::new();
            self.read_impl(&mut record)?;
            self.headers = Some(record);
        }
        Ok(self.headers.as_ref().unwrap().clone())
    }

    pub fn read_byte_record(&mut self, record: &mut ByteRecord) -> Result<bool> {
        if !self.seeked && !self.opts.has_headers && !self.first {
            if let Some(ref headers) = self.headers {
                self.first = true;
                *record = headers.clone();
                return Ok(!record.is_empty());
            }
        }
        let ok = self.read_impl(record)?;
        self.first = true;
        if !self.seeked && self.headers.is_none() {
            self.headers = Some(record.clone());
            if self.opts.has_headers {
                return self.read_impl(record);
            }
        }
        Ok(ok)
    }

    /// Iterate over records; errors are yielded and iteration continues.
    pub fn next_record(&mut self) -> Option<Result<ByteRecord>> {
        let mut r = ByteRecord::new();
        match self.read_byte_record(&mut r) {
            Ok(true) => Some(Ok(r)),
            Ok(false) => None,
            Err(e) => Some(Err(e)),
        }
    }

    pub fn records(&mut self) -> Records<'_, R> {
        Records { rdr: self }
    }
}

pub struct Records<'a, R> {
    rdr: &'a mut Reader<R>,
}

impl<'a, R: Read> Iterator for Records<'a, R> {
    type Item = Result<ByteRecord>;
    fn next(&mut self) -> Option<Result<ByteRecord>> {
        self.rdr.next_record()
    }
}

impl<R: Read + Seek> Reader<R> {
    pub fn seek(&mut self, pos: Position) -> Result<()> {
        self.byte_headers()?;
        self.seeked = true;
        if pos.byte == self.cur_pos.byte {
