        self.blen = 0;
        self.state = St::StartRecord;
        self.line = pos.line;
        self.has_read = false;
        self.cur_pos = pos;
        self.eof = Eof::NotEof;
        Ok(())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum QuoteStyle {
    Necessary,
    Always,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Terminator {
    Crlf,
    Any(u8),
}

#[derive(Clone, Copy, Debug)]
pub struct WriterOptions {
    pub delimiter: u8,
    pub quote: u8,
    pub escape: u8,
    pub double_quote: bool,
    pub style: QuoteStyle,
    pub term: Terminator,
    pub flexible: bool,
}

pub struct Writer<W: Write> {
    w: Option<W>,
    buf: Vec<u8>,
    opts: WriterOptions,
    requires_quotes: [bool; 256],
    first_field_count: Option<u64>,
    fields_written: u64,
    record_bytes: u64,
}

const WBUF: usize = 32 * (1 << 10);

impl<W: Write> Writer<W> {
    pub fn new(w: W, opts: WriterOptions) -> Writer<W> {
        let mut rq = [false; 256];
        rq[opts.delimiter as usize] = true;
        rq[opts.quote as usize] = true;
        if !opts.double_quote {
            rq[opts.escape as usize] = true;
        }
        match opts.term {
            Terminator::Crlf | Terminator::Any(b'\n') | Terminator::Any(b'\r') => {
                rq[b'\r' as usize] = true;
                rq[b'\n' as usize] = true;
            }
            Terminator::Any(b) => {
                rq[b as usize] = true;
            }
        }
        Writer {
            w: Some(w),
            buf: Vec::with_capacity(WBUF),
            opts,
            requires_quotes: rq,
            first_field_count: None,
            fields_written: 0,
            record_bytes: 0,
        }
    }

    pub fn get_mut(&mut self) -> &mut W {
        self.w.as_mut().unwrap()
    }

    fn should_quote(&self, field: &[u8]) -> bool {
        match self.opts.style {
            QuoteStyle::Always => true,
            QuoteStyle::Necessary => field.iter().any(|&b| self.requires_quotes[b as usize]),
        }
    }

    pub fn write_field(&mut self, field: &[u8]) -> Result<()> {
        if self.fields_written > 0 {
            self.buf.push(self.opts.delimiter);
            self.record_bytes += 1;
        }
        let start = self.buf.len();
        if self.should_quote(field) {
            let q = self.opts.quote;
            self.buf.push(q);
            for &b in field {
                if b == q {
                    if self.opts.double_quote {
                        self.buf.push(q);
                    } else {
                        self.buf.push(self.opts.escape);
                    }
                }
                self.buf.push(b);
            }
            self.buf.push(q);
        } else {
            self.buf.extend_from_slice(field);
        }
        self.record_bytes += (self.buf.len() - start) as u64;
        self.fields_written += 1;
        Ok(())
    }

    pub fn write_terminator(&mut self) -> Result<()> {
        if !self.opts.flexible {
            match self.first_field_count {
                None => self.first_field_count = Some(self.fields_written),
                Some(expected) => {
                    if expected != self.fields_written {
                        return Err(Error::UnequalLengths {
                            pos: None,
                            expected_len: expected,
                            len: self.fields_written,
                        });
                    }
                }
            }
        }
        if self.record_bytes == 0 {
            let q = self.opts.quote;
            self.buf.push(q);
            self.buf.push(q);
        }
        match self.opts.term {
            Terminator::Crlf => self.buf.extend_from_slice(b"\r\n"),
            Terminator::Any(b) => self.buf.push(b),
        }
        self.fields_written = 0;
        self.record_bytes = 0;
        if self.buf.len() >= WBUF {
            self.flush_buf()?;
        }
        Ok(())
    }

    pub fn write_record<'a, I: IntoIterator<Item = &'a [u8]>>(&mut self, it: I) -> Result<()> {
        for f in it {
            self.write_field(f)?;
        }
        self.write_terminator()
    }

    pub fn write_byte_record(&mut self, r: &ByteRecord) -> Result<()> {
        self.write_record(r.iter())
    }

    fn flush_buf(&mut self) -> Result<()> {
        if !self.buf.is_empty() {
            let res = self.w.as_mut().unwrap().write_all(&self.buf);
            self.buf.clear();
            res?;
        }
        Ok(())
    }

    pub fn flush(&mut self) -> Result<()> {
        self.flush_buf()?;
        self.w.as_mut().unwrap().flush()?;
        Ok(())
    }
}

impl<W: Write> Drop for Writer<W> {
    fn drop(&mut self) {
        if self.w.is_some() {
            let _ = self.flush();
        }
    }
}
