    pub fn new(w: W) -> TabWriter<W> {
        TabWriter {
            w,
            buf: Vec::with_capacity(1024),
            lines: vec![vec![]],
            curcell: Cell::default(),
            minwidth: 2,
            padding: 2,
        }
    }

    pub fn minwidth(mut self, n: usize) -> TabWriter<W> {
        self.minwidth = n;
        self
    }

    pub fn padding(mut self, n: usize) -> TabWriter<W> {
        self.padding = n;
        self
    }

    fn reset(&mut self) {
        self.buf.clear();
        self.lines = vec![vec![]];
        self.curcell = Cell::default();
    }

    fn add_bytes(&mut self, bytes: &[u8]) {
        self.curcell.size += bytes.len();
        self.buf.extend_from_slice(bytes);
    }

    fn term_curcell(&mut self) {
        let start = self.buf.len();
        let mut cell = std::mem::replace(
            &mut self.curcell,
            Cell { start, width: 0, size: 0 },
        );
        cell.width = display_columns(&self.buf[cell.start..cell.start + cell.size]);
        self.lines.last_mut().unwrap().push(cell);
    }
}

fn display_columns(bytes: &[u8]) -> usize {
    match std::str::from_utf8(bytes) {
        Err(_) => bytes.len(),
        Ok(s) => s.chars().map(|c| c.width().unwrap_or(0)).sum(),
    }
}

fn cell_widths(lines: &[Vec<Cell>], minwidth: usize) -> Vec<Vec<usize>> {
    let mut ws: Vec<Vec<usize>> = (0..lines.len()).map(|_| vec![]).collect();
    for (i, iline) in lines.iter().enumerate() {
        if iline.is_empty() {
            continue;
        }
        for col in ws[i].len()..(iline.len() - 1) {
            let mut width = minwidth;
            let mut contig_count = 0;
            for line in lines[i..].iter() {
                if col + 1 >= line.len() {
                    break;
                }
                contig_count += 1;
                width = cmp::max(width, line[col].width);
            }
            for j in i..(i + contig_count) {
                ws[j].push(width);
            }
        }
    }
    ws
}

impl<W: Write> Write for TabWriter<W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let mut lastterm = 0usize;
