use std::fs;
use std::io::{self, Read, Seek, SeekFrom};

use crate::csv;

pub struct Indexed {
    pub rdr: csv::Reader<fs::File>,
    idx: fs::File,
    len: u64,
}

fn read_u64(f: &mut fs::File) -> io::Result<u64> {
    let mut buf = [0u8; 8];
    f.read_exact(&mut buf)?;
    Ok(u64::from_be_bytes(buf))
}

impl Indexed {
    pub fn open(rdr: csv::Reader<fs::File>, mut idx: fs::File) -> csv::Result<Indexed> {
        idx.seek(SeekFrom::End(-8))?;
        let len = read_u64(&mut idx)?;
        Ok(Indexed { rdr, idx, len })
    }

    pub fn count(&self) -> u64 {
        if self.rdr.has_headers() && self.len > 0 {
            self.len - 1
        } else {
            self.len
        }
    }

    fn get(&mut self, i: u64) -> csv::Result<csv::Position> {
        if i >= self.len {
            let msg = format!("invalid record index {} (there are {} records)", i, self.len);
            return Err(io::Error::new(io::ErrorKind::Other, msg).into());
        }
        self.idx.seek(SeekFrom::Start(i.wrapping_mul(8)))?;
        let offset = read_u64(&mut self.idx)?;
        Ok(csv::Position { byte: offset, line: 1, record: i })
    }

    pub fn seek(&mut self, mut i: u64) -> csv::Result<()> {
        if i >= self.count() {
            let msg = format!(
                "invalid record index {} (there are {} records)",
                i,
                self.count()
            );
            return Err(io::Error::new(io::ErrorKind::Other, msg).into());
        }
        if self.rdr.has_headers() {
            i += 1;
        }
        let pos = self.get(i)?;
        self.rdr.seek(pos)?;
        Ok(())
    }
}

/// Create an index from a CSV reader.
pub fn create<R: Read, W: io::Write>(rdr: &mut csv::Reader<R>, wtr: &mut W) -> csv::Result<()> {
    let mut len: u64 = 0;
    if rdr.has_headers() {
        let header = rdr.byte_headers()?;
        if !header.is_empty() {
            let pos = header.position().unwrap();
            wtr.write_all(&pos.byte.to_be_bytes())?;
            len += 1;
        }
    }
    let mut record = csv::ByteRecord::new();
    while rdr.read_byte_record(&mut record)? {
        let pos = record.position().unwrap();
        wtr.write_all(&pos.byte.to_be_bytes())?;
        len += 1;
    }
    wtr.write_all(&len.to_be_bytes())?;
    Ok(())
}
