//! A minimal docopt-style argument parser, sufficient for xsv's usage strings.

use std::collections::HashMap;

#[derive(Clone, Debug)]
struct OptDesc {
    short: Option<char>,
    long: Option<String>,
    takes_arg: bool,
    default: Option<String>,
}

impl OptDesc {
    fn key(&self) -> String {
        match self.long {
            Some(ref l) => l.clone(),
            None => format!("-{}", self.short.unwrap()),
        }
    }
}

#[derive(Clone, Debug)]
enum Pat {
    Cmd(String),
    Pos(String),
    PosRepeat(String),
    Optional(Vec<Pat>),
    Options,
    Flag(String),
}

#[derive(Clone, Debug)]
pub enum Value {
    Bool(bool),
    Str(Option<String>),
    List(Vec<String>),
}

#[derive(Debug)]
pub enum Error {
    /// Error message to be followed by the usage section.
    Usage(String, String),
    Help(String),
    Version(String),
    Deserialize(String),
}

impl Error {
    pub fn exit(&self) -> ! {
        use std::io::Write;
        match *self {
            Error::Usage(ref msg, ref usage) => {
                eprintln!("{}\n\n{}", msg, usage);
                std::process::exit(1);
            }
            Error::Help(ref doc) => {
                let out = std::io::stdout();
                let mut o = out.lock();
                let _ = writeln!(o, "{}", doc);
                let _ = o.flush();
                std::process::exit(0);
            }
            Error::Version(ref v) => {
                let out = std::io::stdout();
                let mut o = out.lock();
                let _ = writeln!(o, "{}", v);
                let _ = o.flush();
                std::process::exit(0);
            }
            Error::Deserialize(ref msg) => {
                eprintln!("{}", msg);
                std::process::exit(1);
            }
        }
    }
}

pub struct Docopt {
    doc: String,
    usage: String,
    opts: Vec<OptDesc>,
    patterns: Vec<Vec<Pat>>,
    options_first: bool,
    version: Option<String>,
}

pub struct ArgvMap {
    map: HashMap<String, Value>,
}

fn parse_option_line(line: &str) -> OptDesc {
    let t = line.trim_start();
    let spec = match t.find("  ") {
        Some(i) => &t[..i],
        None => t,
    };
    let spec = spec.replace(',', " ").replace('=', " ");
    let mut d = OptDesc { short: None, long: None, takes_arg: false, default: None };
    for tok in spec.split_whitespace() {
        if tok.starts_with("--") {
            d.long = Some(tok.to_owned());
        } else if tok.starts_with('-') {
            d.short = tok[1..].chars().next();
        } else if tok.starts_with('<') {
            d.takes_arg = true;
        }
    }
    d
}

fn find_default(desc: &str) -> Option<String> {
    let lower = desc.to_lowercase();
    if let Some(i) = lower.find("[default: ") {
        let rest = &desc[i + "[default: ".len()..];
        if let Some(j) = rest.rfind(']') {
            return Some(rest[..j].to_owned());
        }
    }
    None
}

fn parse_usage_line(line: &str) -> Vec<Pat> {
    let mut pats = vec![];
    for tok in line.split_whitespace().skip(1) {
        let p = if tok == "[options]" {
            Pat::Options
        } else if tok.starts_with('[') && tok.ends_with(']') {
            let inner = &tok[1..tok.len() - 1];
            vec_single(parse_atom(inner))
        } else {
            parse_atom(tok)
        };
        pats.push(p);
    }
    pats
}

fn vec_single(p: Pat) -> Pat {
    Pat::Optional(vec![p])
}

fn parse_atom(tok: &str) -> Pat {
    if tok.starts_with('<') && tok.ends_with("...") {
        Pat::PosRepeat(tok[..tok.len() - 3].to_owned())
    } else if tok.starts_with('<') {
        Pat::Pos(tok.to_owned())
    } else if tok.starts_with('-') && tok != "--" {
        Pat::Flag(tok.to_owned())
    } else {
        Pat::Cmd(tok.to_owned())
    }
}

impl Docopt {
    pub fn new(doc: &str) -> Docopt {
        let lines: Vec<&str> = doc.lines().collect();
        // Usage section.
        let mut usage_lines: Vec<&str> = vec![];
        let mut patterns = vec![];
        let mut i = 0;
        while i < lines.len() {
            if lines[i].trim_start().to_lowercase().starts_with("usage:") {
                usage_lines.push(lines[i].trim());
                i += 1;
                while i < lines.len() && !lines[i].trim().is_empty() {
                    usage_lines.push(lines[i]);
                    patterns.push(parse_usage_line(lines[i]));
                    i += 1;
                }
                break;
            }
            i += 1;
        }
        let usage = usage_lines.join("\n").trim_end().to_owned();
        // Option descriptions.
        let mut opts: Vec<OptDesc> = vec![];
        let mut i = 0;
        while i < lines.len() {
            let t = lines[i].trim_start();
            if t.starts_with('-') {
                let mut d = parse_option_line(lines[i]);
                let mut desc = String::new();
                if let Some(k) = t.find("  ") {
                    desc.push_str(&t[k..]);
                }
                let mut j = i + 1;
                while j < lines.len() {
                    let tj = lines[j].trim();
                    if tj.is_empty() || tj.starts_with('-') {
                        break;
                    }
                    desc.push('\n');
                    desc.push_str(tj);
                    j += 1;
                }
                if d.takes_arg {
                    for l in desc.lines() {
                        if let Some(def) = find_default(l) {
                            d.default = Some(def);
                            break;
                        }
                    }
                }
                opts.push(d);
                i = j;
                continue;
            }
            i += 1;
        }
        Docopt {
            doc: doc.trim().to_owned(),
            usage,
            opts,
            patterns,
            options_first: false,
            version: None,
        }
    }

    pub fn options_first(mut self, yes: bool) -> Docopt {
        self.options_first = yes;
        self
    }

    pub fn version(mut self, v: Option<String>) -> Docopt {
        self.version = v;
        self
    }

    fn usage_err(&self, msg: String) -> Error {
        Error::Usage(msg, self.usage.clone())
    }

    fn find_long(&self, name: &str) -> Option<&OptDesc> {
        self.opts.iter().find(|o| o.long.as_deref() == Some(name))
    }

    fn find_short(&self, c: char) -> Option<&OptDesc> {
        self.opts.iter().find(|o| o.short == Some(c))
    }

    pub fn parse(&self, argv: &[String]) -> Result<ArgvMap, Error> {
        let args = if argv.is_empty() { &argv[..] } else { &argv[1..] };
        let mut positional: Vec<String> = vec![];
        let mut flags: Vec<(String, Option<String>)> = vec![];
        let mut only_pos = false;
        let mut i = 0;
        while i < args.len() {
            let a = &args[i];
            if only_pos {
                positional.push(a.clone());
                i += 1;
                continue;
            }
            if a == "--" {
                only_pos = true;
                i += 1;
                continue;
            }
            if a.starts_with("--") {
                let (name, val) = match a.find('=') {
                    Some(k) => (&a[..k], Some(a[k + 1..].to_owned())),
                    None => (&a[..], None),
                };
                let opt = match self.find_long(name) {
                    Some(o) => o.clone(),
                    None => return Err(self.usage_err(format!("Unknown flag: '{}'", name))),
                };
                if opt.takes_arg {
                    let v = match val {
                        Some(v) => v,
                        None => {
                            i += 1;
                            if i >= args.len() {
                                return Err(self.usage_err(format!(
                                    "Expected argument for flag '{}' but reached end of arguments.",
                                    name
                                )));
                            }
                            args[i].clone()
                        }
                    };
                    flags.push((opt.key(), Some(v)));
                } else {
                    if let Some(v) = val {
                        return Err(self.usage_err(format!(
                            "Flag '{}' cannot have an argument, but found '{}'.",
                            name, v
                        )));
                    }
                    flags.push((opt.key(), None));
                }
            } else if a.starts_with('-') && a.len() > 1 {
                let chars: Vec<char> = a[1..].chars().collect();
                let mut j = 0;
                while j < chars.len() {
                    let c = chars[j];
                    let opt = match self.find_short(c) {
                        Some(o) => o.clone(),
                        None => return Err(self.usage_err(format!("Unknown flag: '-{}'", c))),
                    };
                    if opt.takes_arg {
                        let rest: String = chars[j + 1..].iter().collect();
                        let v = if !rest.is_empty() {
                            rest
                        } else {
                            i += 1;
                            if i >= args.len() {
                                return Err(self.usage_err(format!(
                                    "Expected argument for flag '{}' but reached end of arguments.",
                                    opt.key()
                                )));
                            }
                            args[i].clone()
                        };
                        flags.push((opt.key(), Some(v)));
                        break;
                    } else {
                        flags.push((opt.key(), None));
                    }
                    j += 1;
                }
            } else {
                positional.push(a.clone());
                if self.options_first {
                    only_pos = true;
                }
            }
            i += 1;
        }

        let mut matched: Option<Vec<(String, Value)>> = None;
        for pat in &self.patterns {
            if let Some(b) = self.try_match(pat, &positional, &flags) {
                matched = Some(b);
                break;
            }
        }
        let bindings = match matched {
            None => return Err(self.usage_err("Invalid arguments.".to_owned())),
            Some(b) => b,
        };

        // Build the full map.
        let mut map: HashMap<String, Value> = HashMap::new();
        for o in &self.opts {
            let v = if o.takes_arg { Value::Str(o.default.clone()) } else { Value::Bool(false) };
            map.insert(o.key(), v);
        }
        for pat in &self.patterns {
            fill_defaults(pat, &mut map);
        }
        for (k, v) in &flags {
            let val = match *v {
                Some(ref s) => Value::Str(Some(s.clone())),
                None => Value::Bool(true),
            };
            map.insert(k.clone(), val);
        }
        for (k, v) in bindings {
            map.insert(k, v);
        }
        let argmap = ArgvMap { map };
        if argmap.get_bool("--help") {
            return Err(Error::Help(self.doc.clone()));
        }
        if let Some(ref v) = self.version {
            if argmap.get_bool("--version") {
                return Err(Error::Version(v.clone()));
            }
        }
        Ok(argmap)
    }

    fn try_match(
        &self,
        pat: &[Pat],
        positional: &[String],
        flags: &[(String, Option<String>)],
    ) -> Option<Vec<(String, Value)>> {
        // Check flags.
        let mut explicit: Vec<String> = vec![];
        let mut has_options = false;
        collect_flags(pat, &mut explicit, &mut has_options, true);
        let mut counts: HashMap<&str, usize> = HashMap::new();
        for (k, _) in flags {
            *counts.entry(k.as_str()).or_insert(0) += 1;
        }
        for (k, c) in &counts {
            if *c > 1 {
                return None;
            }
            let is_explicit = explicit.iter().any(|e| self.canonical(e) == *k);
            if !is_explicit && !has_options {
                return None;
            }
        }
        let mut required: Vec<String> = vec![];
        let mut dummy = false;
        collect_flags_required(pat, &mut required, &mut dummy);
        for r in &required {
            let key = self.canonical(r);
            if !counts.contains_key(key.as_str()) {
                return None;
            }
        }
        let mut b = vec![];
        if match_seq(pat.to_vec(), positional, 0, &mut b) {
            Some(b)
        } else {
            None
        }
    }

    fn canonical(&self, name: &str) -> String {
        if name.starts_with("--") {
            if let Some(o) = self.find_long(name) {
                return o.key();
            }
        } else if let Some(c) = name[1..].chars().next() {
            if let Some(o) = self.find_short(c) {
                return o.key();
            }
        }
        name.to_owned()
    }
}

fn collect_flags(pat: &[Pat], out: &mut Vec<String>, has_options: &mut bool, _top: bool) {
    for p in pat {
        match *p {
            Pat::Flag(ref f) => out.push(f.clone()),
            Pat::Options => *has_options = true,
            Pat::Optional(ref inner) => collect_flags(inner, out, has_options, false),
            _ => {}
        }
    }
}

fn collect_flags_required(pat: &[Pat], out: &mut Vec<String>, _d: &mut bool) {
    for p in pat {
        if let Pat::Flag(ref f) = *p {
            out.push(f.clone());
        }
    }
}

fn fill_defaults(pat: &[Pat], map: &mut HashMap<String, Value>) {
    for p in pat {
        match *p {
            Pat::Cmd(ref c) => {
                map.entry(c.clone()).or_insert(Value::Bool(false));
            }
            Pat::Pos(ref n) => {
                map.entry(n.clone()).or_insert(Value::Str(None));
            }
            Pat::PosRepeat(ref n) => {
                map.entry(n.clone()).or_insert(Value::List(vec![]));
            }
            Pat::Optional(ref inner) => fill_defaults(inner, map),
            _ => {}
        }
    }
}

fn match_seq(pats: Vec<Pat>, pos: &[String], k: usize, b: &mut Vec<(String, Value)>) -> bool {
    if pats.is_empty() {
        return k == pos.len();
    }
    let rest: Vec<Pat> = pats[1..].to_vec();
    match pats[0] {
        Pat::Cmd(ref c) => {
            if k < pos.len() && pos[k] == *c {
                b.push((c.clone(), Value::Bool(true)));
                if match_seq(rest, pos, k + 1, b) {
                    return true;
                }
                b.pop();
            }
            false
        }
        Pat::Pos(ref n) => {
            if k < pos.len() {
                b.push((n.clone(), Value::Str(Some(pos[k].clone()))));
                if match_seq(rest, pos, k + 1, b) {
                    return true;
                }
                b.pop();
            }
            false
        }
        Pat::PosRepeat(ref n) => {
            if k >= pos.len() {
                return false;
            }
            let mut take = pos.len() - k;
            while take >= 1 {
                b.push((n.clone(), Value::List(pos[k..k + take].to_vec())));
                if match_seq(rest.clone(), pos, k + take, b) {
                    return true;
                }
                b.pop();
                take -= 1;
            }
            false
        }
        Pat::Optional(ref inner) => {
            let mut seq = inner.clone();
            seq.extend(rest.iter().cloned());
            let save = b.len();
            if match_seq(seq, pos, k, b) {
                return true;
            }
            b.truncate(save);
            match_seq(rest, pos, k, b)
        }
        Pat::Options | Pat::Flag(_) => match_seq(rest, pos, k, b),
    }
}

impl ArgvMap {
    pub fn get_bool(&self, key: &str) -> bool {
        match self.map.get(key) {
            Some(Value::Bool(b)) => *b,
            Some(Value::Str(Some(_))) => true,
            Some(Value::List(l)) => !l.is_empty(),
            _ => false,
        }
    }

    pub fn get_str(&self, key: &str) -> Option<String> {
        match self.map.get(key) {
            Some(Value::Str(s)) => s.clone(),
            Some(Value::List(l)) => l.first().cloned(),
            _ => None,
        }
    }

    pub fn get_vec(&self, key: &str) -> Vec<String> {
        match self.map.get(key) {
            Some(Value::List(l)) => l.clone(),
            Some(Value::Str(Some(s))) => vec![s.clone()],
            _ => vec![],
        }
    }

    /// A string value, defaulting to the empty string.
    pub fn string(&self, key: &str) -> String {
        self.get_str(key).unwrap_or_default()
    }

    pub fn opt_u64(&self, key: &str) -> Result<Option<u64>, Error> {
        match self.get_str(key) {
            None => Ok(None),
            Some(s) => match s.parse::<u64>() {
                Ok(n) => Ok(Some(n)),
                Err(_) => Err(Error::Deserialize(format!(
                    "Could not deserialize '{}' to u64 for '{}'.",
                    s, key
                ))),
            },
        }
    }

    pub fn u64(&self, key: &str) -> Result<u64, Error> {
        let s = self.string(key);
        match s.parse::<u64>() {
            Ok(n) => Ok(n),
            Err(_) => Err(Error::Deserialize(format!(
                "Could not deserialize '{}' to u64 for '{}'.",
                s, key
            ))),
        }
    }

    pub fn opt_usize(&self, key: &str) -> Result<Option<usize>, Error> {
        self.opt_u64(key).map(|o| o.map(|n| n as usize))
    }

    pub fn usize(&self, key: &str) -> Result<usize, Error> {
        self.u64(key).map(|n| n as usize)
    }

    /// Parses a delimiter-like value (a single ASCII character, or `\t`).
    pub fn opt_delim(&self, key: &str) -> Result<Option<u8>, Error> {
        match self.get_str(key) {
            None => Ok(None),
            Some(s) => parse_delim(&s).map(Some).map_err(Error::Deserialize),
        }
    }

    pub fn delim(&self, key: &str) -> Result<u8, Error> {
        let s = self.string(key);
        parse_delim(&s).map_err(Error::Deserialize)
    }
}

pub fn parse_delim(s: &str) -> Result<u8, String> {
    if s == r"\t" {
        return Ok(b'\t');
    }
    if s.len() != 1 {
        return Err(format!("Could not convert '{}' to a single ASCII character.", s));
    }
    let c = s.chars().next().unwrap();
    if c.is_ascii() {
        Ok(c as u8)
    } else {
        Err(format!("Could not convert '{}' to ASCII delimiter.", c))
    }
}
