        'a' | 'f' | 't' | 'n' | 'r' | 'v' => true,
        'd' | 'D' | 's' | 'S' | 'w' | 'W' => true,
        'p' | 'P' | 'x' | 'u' | 'U' => true,
        '0'..='9' => true,
        'b' | 'B' | 'A' | 'z' => !in_class || true,
        _ => false,
    }
}

/// Rewrites the pattern so that constructs rejected by the old regex syntax
/// are also rejected (at the same position) by the current regex parser.
/// The rewritten pattern has exactly the same characters at all positions
/// except the rewritten ones.
fn rewrite(pattern: &str) -> Vec<char> {
    let mut cs: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    let mut class_depth = 0usize;
    while i < cs.len() {
        let c = cs[i];
        if c == '\\' {
            if i + 1 < cs.len() {
                let e = cs[i + 1];
                if !is_old_escapable(e) && !is_old_special_escape(e, class_depth > 0) {
                    cs[i + 1] = 'e';
                }
                i += 2;
            } else {
                i += 1;
            }
            continue;
        }
        if class_depth > 0 {
            if c == '[' {
                // Nested class or ASCII class.
                if i + 1 < cs.len() && cs[i + 1] == ':' {
                    // [:name:]
                    let mut j = i + 2;
                    while j + 1 < cs.len() && !(cs[j] == ':' && cs[j + 1] == ']') {
                        j += 1;
                    }
                    if j + 1 < cs.len() {
                        i = j + 2;
                        continue;
                    }
                }
                class_depth += 1;
                i += 1;
                i = skip_class_open(&cs, i);
                continue;
            }
            if c == ']' {
                class_depth -= 1;
            }
            i += 1;
            continue;
        }
        match c {
            '[' => {
                class_depth += 1;
                i += 1;
                i = skip_class_open(&cs, i);
            }
            '(' => {
                if i + 1 < cs.len() && cs[i + 1] == '?' {
                    let mut j = i + 2;
                    if j < cs.len() && cs[j] == '<' {
                        let next = cs.get(j + 1).cloned();
                        if next != Some('=') && next != Some('!') {
                            cs[j] = 'Q';
                        }
                        i = j + 1;
                        continue;
                    }
                    if j < cs.len() && cs[j] == 'P' {
                        i = j + 1;
                        continue;
                    }
                    while j < cs.len() && cs[j] != ':' && cs[j] != ')' {
                        if cs[j] == 'R' {
                            cs[j] = 'Q';
                        }
                        if !(cs[j].is_ascii_alphabetic() || cs[j] == '-') {
                            break;
                        }
                        j += 1;
                    }
                    i = j;
                    continue;
                }
                i += 1;
            }
            _ => i += 1,
        }
    }
    cs
