/// After an opening `[` (or `[^`), a leading `]` is a literal.
fn skip_class_open(cs: &[char], mut i: usize) -> usize {
    if i < cs.len() && cs[i] == '^' {
        i += 1;
    }
    if i < cs.len() && cs[i] == ']' {
        i += 1;
    }
    i
}

pub fn debug_syntax(msg: &str) -> String {
    let hr: String = std::iter::repeat('~').take(79).collect();
    format!("Syntax(\n{}\n{}\n{}\n)", hr, msg, hr)
}

pub fn build(pattern: &str, case_insensitive: bool) -> Result<Regex, String> {
    let rewritten: String = rewrite(pattern).into_iter().collect();
    match RegexBuilder::new(&rewritten)
        .case_insensitive(case_insensitive)
        .build()
    {
        Ok(re) => Ok(re),
        Err(regex::Error::Syntax(msg)) => {
            let mut msg = msg;
            if rewritten != pattern {
                let olines: Vec<&str> = pattern.split('\n').collect();
                let rlines: Vec<&str> = rewritten.split('\n').collect();
                let mut out = String::new();
                for (k, line) in msg.split('\n').enumerate() {
                    if k > 0 {
                        out.push('\n');
                    }
                    let mut replaced = line.to_owned();
                    for (o, r) in olines.iter().zip(rlines.iter()) {
                        if o != r && !r.is_empty() && line.ends_with(r) {
                            let prefix = &line[..line.len() - r.len()];
                            if prefix.trim().is_empty() || prefix.trim_end().ends_with(':') {
                                replaced = format!("{}{}", prefix, o);
                                break;
                            }
                        }
                    }
                    out.push_str(&replaced);
                }
                msg = out;
            }
            let msg = msg.replace(
                "error: repetition quantifier expects a valid decimal",
                "error: decimal literal empty",
            );
            Err(debug_syntax(&msg))
        }
        Err(e) => Err(format!("{:?}", e)),
    }
}
