{"command":"cd /workspace/src && cat > main.rs <<'EOF'
mod cmd;
mod config;
mod csv;
mod docopt;
mod index;
mod oldre;
mod rng;
mod select;
mod tabwriter;
mod util;

use std::fmt;
use std::io::{self, Write};
use std::process;

const USAGE: &str = include_str!("usage/main.txt");
const COMMAND_LIST: &str = include_str!("usage/command_list.txt");

const VARIANTS: &[&str] = &[
    "cat", "count", "fixlengths", "flatten", "fmt", "frequency", "headers", "help", "index",
    "input", "join", "partition", "reverse", "sample", "search", "select", "slice", "sort",
    "split", "stats", "table",
];

pub enum CliError {
    Flag(docopt::Error),
    Csv(csv::Error),
    Io(io::Error),
    Other(String),
}

pub type CliResult<T> = Result<T, CliError>;

impl fmt::Display for CliError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            CliError::Flag(ref e) => write!(f, "{:?}", e),
            CliError::Csv(ref e) => e.fmt(f),
            CliError::Io(ref e) => e.fmt(f),
            CliError::Other(ref s) => f.write_str(s),
        }
    }
}

impl From<docopt::Error> for CliError {
    fn from(err: docopt::Error) -> CliError {
        CliError::Flag(err)
    }
}

impl From<csv::Error> for CliError {
    fn from(err: csv::Error) -> CliError {
        match err {
            csv::Error::Io(e) => CliError::Io(e),
            e => CliError::Csv(e),
        }
    }
}

impl From<io::Error> for CliError {
    fn from(err: io::Error) -> CliError {
        CliError::Io(err)
    }
}

impl From<String> for CliError {
    fn from(err: String) -> CliError {
        CliError::Other(err)
    }
}

impl<'a> From<&'a str> for CliError {
    fn from(err: &'a str) -> CliError {
        CliError::Other(err.to_owned())
    }
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let d = docopt::Docopt::new(USAGE)
        .options_first(true)
        .version(Some(util::VERSION.to_owned()));
    let args = match d.parse(&argv) {
        Ok(a) => a,
        Err(e) => e.exit(),
    };
    let command = args.get_str("<command>");
    if args.get_bool("--list") {
        let out = io::stdout();
        let mut o = out.lock();
        let _ = write!(o, "Installed commands:\n{}\n\n", COMMAND_LIST);
        let _ = o.flush();
        return;
    }
    let command = match command {
        None => {
            eprint!(
                "xsv is a suite of CSV command line utilities.\n\nPlease choose one of the following commands:\n{}\n\n",
                COMMAND_LIST
            );
            process::exit(0);
        }
        Some(c) => c,
    };
    let lc = command.to_lowercase();
    if !VARIANTS.contains(&lc.as_str()) {
        let list: Vec<String> = VARIANTS.iter().map(|v| format!("\"{}\"", v)).collect();
        eprintln!(
            "Could not match '{}' with any of the allowed variants: [{}]",
            lc,
            list.join(", ")
        );
        process::exit(1);
    }
    let result = if !argv[1].chars().all(char::is_lowercase) {
        Err(CliError::Other(format!(
            "xsv expects commands in lowercase. Did you mean '{}'?",
            argv[1].to_lowercase()
        )))
    } else {
        cmd::run(&lc, &argv)
    };
    match result {
        Ok(()) => process::exit(0),
        Err(CliError::Flag(err)) => err.exit(),
        Err(CliError::Csv(err)) => {
            eprintln!("{}", err);
            process::exit(1);
        }
        Err(CliError::Io(ref err)) if err.kind() == io::ErrorKind::BrokenPipe => {
            process::exit(0);
        }
        Err(CliError::Io(err)) => {
            eprintln!("{}", err);
            process::exit(1);
        }
        Err(CliError::Other(msg)) => {
            eprintln!("{}", msg);
            process::exit(1);
        }
    }
}
EOF"}

