//! sampling behaviour expected from xsv.

pub struct Hc128 {
    t: [u32; 1024],
    counter1024: usize,
    results: [u32; 16],
    index: usize,
}

#[inline]
fn f1(x: u32) -> u32 {
    x.rotate_right(7) ^ x.rotate_right(18) ^ (x >> 3)
}

#[inline]
fn f2(x: u32) -> u32 {
    x.rotate_right(17) ^ x.rotate_right(19) ^ (x >> 10)
}

impl Hc128 {
    pub fn from_seed(seed: [u8; 32]) -> Hc128 {
        let mut s = [0u32; 8];
        for i in 0..8 {
            s[i] = u32::from_le_bytes([seed[4 * i], seed[4 * i + 1], seed[4 * i + 2], seed[4 * i + 3]]);
        }
        let mut t = [0u32; 1024];
        t[..4].copy_from_slice(&s[..4]);
        t[4..8].copy_from_slice(&s[..4]);
        t[8..12].copy_from_slice(&s[4..]);
        t[12..16].copy_from_slice(&s[4..]);
        for i in 16..256 + 16 {
            t[i] = f2(t[i - 2])
                .wrapping_add(t[i - 7])
                .wrapping_add(f1(t[i - 15]))
                .wrapping_add(t[i - 16])
                .wrapping_add(i as u32);
        }
        let tmp: Vec<u32> = t[256..272].to_vec();
        t[0..16].copy_from_slice(&tmp);
        for i in 16..1024 {
            t[i] = f2(t[i - 2])
                .wrapping_add(t[i - 7])
                .wrapping_add(f1(t[i - 15]))
                .wrapping_add(t[i - 16])
                .wrapping_add(256 + i as u32);
        }
        let mut core = Hc128 { t, counter1024: 0, results: [0; 16], index: 16 };
        for _ in 0..1024 {
            let j = core.counter1024 % 512;
            if core.counter1024 < 512 {
                let v = core.step_p(j);
                core.t[j] = v;
            } else {
                let v = core.step_q(j);
                core.t[512 + j] = v;
            }
            core.counter1024 += 1;
        }
        core.counter1024 = 0;
        core
    }

    pub fn from_u64(seed: u64) -> Hc128 {
        let mut buf = [0u8; 32];
        buf[..8].copy_from_slice(&seed.to_le_bytes());
        Hc128::from_seed(buf)
    }

    pub fn from_entropy() -> Hc128 {
        use std::io::Read;
        let mut buf = [0u8; 32];
        let ok = std::fs::File::open("/dev/urandom")
            .and_then(|mut f| f.read_exact(&mut buf))
            .is_ok();
        if !ok {
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos())
                .unwrap_or(0);
            let pid = std::process::id() as u128;
            let v = now ^ (pid << 64);
            buf[..16].copy_from_slice(&v.to_le_bytes());
        }
        Hc128::from_seed(buf)
    }

    fn step_p(&mut self, j: usize) -> u32 {
        let t0 = self.t[(j + 1) % 512].rotate_right(23);
        let t1 = self.t[(j + 512 - 3) % 512].rotate_right(10);
        let t2 = self.t[(j + 512 - 10) % 512].rotate_right(8);
        self.t[j] = self.t[j].wrapping_add(t2).wrapping_add(t0 ^ t1);
        let x = self.t[(j + 512 - 12) % 512];
        let a = (x & 0xff) as usize;
        let c = ((x >> 16) & 0xff) as usize;
        let h = self.t[512 + a].wrapping_add(self.t[512 + 256 + c]);
        h ^ self.t[j]
    }

    fn step_q(&mut self, j: usize) -> u32 {
        let t0 = self.t[512 + (j + 1) % 512].rotate_left(23);
        let t1 = self.t[512 + (j + 512 - 3) % 512].rotate_left(10);
        let t2 = self.t[512 + (j + 512 - 10) % 512].rotate_left(8);
        self.t[512 + j] = self.t[512 + j].wrapping_add(t2).wrapping_add(t0 ^ t1);
        let x = self.t[512 + (j + 512 - 12) % 512];
        let a = (x & 0xff) as usize;
        let c = ((x >> 16) & 0xff) as usize;
        let h = self.t[a].wrapping_add(self.t[256 + c]);
        h ^ self.t[512 + j]
    }

    fn generate(&mut self) {
        for k in 0..16 {
            let j = self.counter1024 % 512;
            let v = if self.counter1024 & 512 == 0 { self.step_p(j) } else { self.step_q(j) };
            self.results[k] = v;
            self.counter1024 = (self.counter1024 + 1) % 1024;
        }
    }

    pub fn next_u32(&mut self) -> u32 {
        if self.index >= 16 {
            self.generate();
            self.index = 0;
        }
        let v = self.results[self.index];
        self.index += 1;
        v
    }

    pub fn next_u64(&mut self) -> u64 {
        let i = self.index;
        if i < 15 {
            self.index += 2;
            (self.results[i] as u64) | ((self.results[i + 1] as u64) << 32)
        } else if i >= 16 {
            self.generate();
            self.index = 2;
            (self.results[0] as u64) | ((self.results[1] as u64) << 32)
        } else {
            let x = self.results[15] as u64;
            self.generate();
            self.index = 1;
            x | ((self.results[0] as u64) << 32)
        }
    }

    /// Uniformly sample from [low, high).
    pub fn gen_range(&mut self, low: u64, high: u64) -> u64 {
        let range = high.wrapping_sub(low);
        let zone = (range << range.leading_zeros()).wrapping_sub(1);
        loop {
            let v = self.next_u64();
            let m = (v as u128) * (range as u128);
            let hi = (m >> 64) as u64;
            let lo = m as u64;
            if lo <= zone {
                return low.wrapping_add(hi);
            }
        }
    }

    pub fn shuffle<T>(&mut self, values: &mut [T]) {
        let mut i = values.len();
        while i >= 2 {
            i -= 1;
            let j = self.gen_range(0, (i + 1) as u64) as usize;
            values.swap(i, j);
        }
    }
}
