use crate::cmd::{get_args, many_configs};
use crate::config::Config;
use crate::csv::ByteRecord;
use crate::CliResult;

const USAGE: &str = include_str!("../usage/cat.txt");

struct Args {
    cmd_rows: bool,
    cmd_columns: bool,
    arg_input: Vec<String>,
    flag_pad: bool,
    flag_output: Option<String>,
    flag_no_headers: bool,
    flag_delimiter: Option<u8>,
}

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = get_args(USAGE, argv)?;
    let args = Args {
        cmd_rows: a.get_bool("rows"),
        cmd_columns: a.get_bool("columns"),
        arg_input: a.get_vec("<input>"),
        flag_pad: a.get_bool("--pad"),
        flag_output: a.get_str("--output"),
        flag_no_headers: a.get_bool("--no-headers"),
        flag_delimiter: a.opt_delim("--delimiter")?,
    };
    if args.cmd_rows {
        args.cat_rows()
    } else if args.cmd_columns {
        args.cat_columns()
    } else {
        unreachable!();
    }
}

impl Args {
    fn configs(&self) -> CliResult<Vec<Config>> {
        Ok(many_configs(&self.arg_input, self.flag_delimiter, self.flag_no_headers)?)
    }

    fn cat_rows(&self) -> CliResult<()> {
        let mut row = ByteRecord::new();
        let mut wtr = Config::new(&self.flag_output).writer()?;
        for (i, conf) in self.configs()?.into_iter().enumerate() {
            let mut rdr = conf.reader()?;
            if i == 0 {
                conf.write_headers(&mut rdr, &mut wtr)?;
            }
            while rdr.read_byte_record(&mut row)? {
                wtr.write_byte_record(&row)?;
            }
        }
        wtr.flush()?;
        Ok(())
    }

    fn cat_columns(&self) -> CliResult<()> {
        let mut wtr = Config::new(&self.flag_output).writer()?;
        let mut rdrs = vec![];
        for conf in self.configs()?.into_iter() {
            rdrs.push(conf.no_headers(true).reader()?);
        }
        let mut lengths = vec![];
        for rdr in rdrs.iter_mut() {
            lengths.push(rdr.byte_headers()?.len());
        }
        'OUTER: loop {
            let mut record = ByteRecord::new();
            let mut num_done = 0;
            for (rdr, &len) in rdrs.iter_mut().zip(lengths.iter()) {
                match rdr.next_record() {
                    None => {
                        num_done += 1;
                        if self.flag_pad {
                            for _ in 0..len {
                                record.push_field(b"");
                            }
                        } else {
                            break 'OUTER;
                        }
                    }
                    Some(Err(err)) => return Err(err.into()),
                    Some(Ok(next)) => record.extend_from(&next),
                }
            }
            if num_done >= rdrs.len() {
                break 'OUTER;
            }
            wtr.write_byte_record(&record)?;
        }
        wtr.flush()?;
        Ok(())
    }
}
