use crate::tabwriter::TabWriter;
use crate::CliResult;

const USAGE: &str = include_str!("../usage/headers.txt");

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = get_args(USAGE, argv)?;
    let arg_input = a.get_vec("<input>");
