use std::collections::HashMap;

use crate::cmd::get_args;
use crate::config::Config;
use crate::csv::{self, ByteRecord};
use crate::index::Indexed;
use crate::select::{SelectColumns, Selection};
use crate::util;
use crate::CliResult;

const USAGE: &str = include_str!("../usage/frequency.txt");

/// A frequency table that remembers insertion order (used to break ties).
#[derive(Clone, Default)]
pub struct Frequencies {
    map: HashMap<Vec<u8>, usize>,
    data: Vec<(Vec<u8>, u64)>,
}

impl Frequencies {
    fn add(&mut self, v: Vec<u8>) {
        if let Some(&i) = self.map.get(&v) {
            self.data[i].1 += 1;
        } else {
            self.map.insert(v.clone(), self.data.len());
            self.data.push((v, 1));
        }
    }

    fn merge(&mut self, other: Frequencies) {
        for (v, c) in other.data.into_iter() {
            if let Some(&i) = self.map.get(&v) {
                self.data[i].1 += c;
            } else {
                self.map.insert(v.clone(), self.data.len());
                self.data.push((v, c));
            }
        }
    }

    fn most_frequent(&self) -> Vec<(Vec<u8>, u64)> {
        let mut counts = self.data.clone();
        counts.sort_by(|a, b| b.1.cmp(&a.1));
        counts
    }

    fn least_frequent(&self) -> Vec<(Vec<u8>, u64)> {
        let mut counts = self.data.clone();
        counts.sort_by(|a, b| a.1.cmp(&b.1));
        counts
    }
}

struct Args {
    arg_input: Option<String>,
    flag_select: SelectColumns,
    flag_limit: usize,
    flag_asc: bool,
    flag_no_nulls: bool,
    flag_jobs: usize,
    flag_output: Option<String>,
    flag_no_headers: bool,
    flag_delimiter: Option<u8>,
}

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = get_args(USAGE, argv)?;
    let arg_input = a.get_str("<input>");
    let flag_select = SelectColumns::parse(&a.string("--select"))
        .map_err(crate::docopt::Error::Deserialize)?;
    let flag_limit = a.usize("--limit")?;
    let flag_asc = a.get_bool("--asc");
    let flag_no_nulls = a.get_bool("--no-nulls");
    let flag_jobs = a.usize("--jobs")?;
    let flag_output = a.get_str("--output");
    let flag_no_headers = a.get_bool("--no-headers");
    let flag_delimiter = a.opt_delim("--delimiter")?;
    let args = Args {
        arg_input,
        flag_select,
        flag_limit,
        flag_asc,
        flag_no_nulls,
        flag_jobs,
        flag_output,
        flag_no_headers,
        flag_delimiter,
    };

    let rconf = args.rconfig();
    let mut wtr = Config::new(&args.flag_output).writer()?;
    let (headers, tables) = match args.rconfig().indexed()? {
        Some(idx) if args.njobs() > 1 => args.parallel_ftables(idx),
        _ => args.sequential_ftables(),
    }?;

    wtr.write_record(vec![&b"field"[..], b"value", b"count"])?;
    for (i, (header, ftab)) in headers.into_iter().zip(tables.into_iter()).enumerate() {
        let mut header = header;
        if rconf.no_headers {
            header = (i + 1).to_string().into_bytes();
        }
        for (value, count) in args.counts(&ftab).into_iter() {
            let count = count.to_string();
            wtr.write_record(vec![&*header, &*value, count.as_bytes()])?;
        }
    }
    wtr.flush()?;
    Ok(())
}

impl Args {
    fn rconfig(&self) -> Config {
        Config::new(&self.arg_input)
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
            .select(self.flag_select.clone())
    }

    fn njobs(&self) -> usize {
        if self.flag_jobs == 0 {
            util::num_cpus()
        } else {
            self.flag_jobs
        }
    }

    fn counts(&self, ftab: &Frequencies) -> Vec<(Vec<u8>, u64)> {
        let mut counts = if self.flag_asc {
            ftab.least_frequent()
        } else {
            ftab.most_frequent()
        };
        if self.flag_limit > 0 {
            counts.truncate(self.flag_limit);
        }
        counts
            .into_iter()
            .map(|(bs, c)| {
                if bs.is_empty() {
                    (b"(NULL)".to_vec(), c)
                } else {
                    (bs, c)
                }
            })
            .collect()
    }

    fn sequential_ftables(&self) -> CliResult<(Vec<Vec<u8>>, Vec<Frequencies>)> {
        let mut rdr = self.rconfig().reader()?;
        let (headers, sel) = self.sel_headers(&mut rdr)?;
