            acc = Some(match acc {
                None => tabs,
                Some(mut a) => {
                    for (x, y) in a.iter_mut().zip(tabs.into_iter()) {
                        x.merge(y);
                    }
                    a
                }
            });
        }
        Ok((headers, acc.unwrap_or_default()))
    }

    fn ftables<I>(&self, sel: &Selection, it: I) -> CliResult<Vec<Frequencies>>
    where
        I: Iterator<Item = csv::Result<ByteRecord>>,
