use crate::CliResult;

const USAGE: &str = include_str!("../usage/frequency.txt");

/// A frequency table that remembers insertion order (used to break ties).
#[derive(Clone, Default)]
pub struct Frequencies {
    map: HashMap<Vec<u8>, usize>,
    data: Vec<(Vec<u8>, u64)>,
}

impl Frequencies {
    fn add(&mut self, v: Vec<u8>) {
        if let Some(&i) = self.map.get(&v) {
            self.data[i].1 += 1;
        } else {
            self.map.insert(v.clone(), self.data.len());
            self.data.push((v, 1));
        }
    }

    fn merge(&mut self, other: Frequencies) {
        for (v, c) in other.data.into_iter() {
            if let Some(&i) = self.map.get(&v) {
                self.data[i].1 += c;
            } else {
                self.map.insert(v.clone(), self.data.len());
                self.data.push((v, c));
            }
        }
    }

    fn most_frequent(&self) -> Vec<(Vec<u8>, u64)> {
        let mut counts = self.data.clone();
        counts.sort_by(|a, b| b.1.cmp(&a.1));
        counts
    }

    fn least_frequent(&self) -> Vec<(Vec<u8>, u64)> {
        let mut counts = self.data.clone();
        counts.sort_by(|a, b| a.1.cmp(&b.1));
        counts
    }
}

struct Args {
    arg_input: Option<String>,
