use std::collections::HashMap;
use std::fs;
use std::io::Write;
use std::str;

use crate::cmd::get_args;
use crate::config::Config;
use crate::csv::{self, ByteRecord, Position};
use crate::docopt;
use crate::select::{SelectColumns, Selection};
use crate::CliResult;

const USAGE: &str = include_str!("../usage/join.txt");

struct Args {
    arg_columns1: SelectColumns,
    arg_input1: String,
    arg_columns2: SelectColumns,
    arg_input2: String,
    flag_left: bool,
    flag_right: bool,
    flag_full: bool,
    flag_cross: bool,
    flag_output: Option<String>,
    flag_no_headers: bool,
    flag_no_case: bool,
    flag_nulls: bool,
    flag_delimiter: Option<u8>,
}

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = get_args(USAGE, argv)?;
    let arg_columns1 =
        SelectColumns::parse(&a.string("<columns1>")).map_err(docopt::Error::Deserialize)?;
    let arg_input1 = a.string("<input1>");
    let arg_columns2 =
        SelectColumns::parse(&a.string("<columns2>")).map_err(docopt::Error::Deserialize)?;
    let arg_input2 = a.string("<input2>");
    let args = Args {
        arg_columns1,
        arg_input1,
        arg_columns2,
        arg_input2,
        flag_left: a.get_bool("--left"),
        flag_right: a.get_bool("--right"),
        flag_full: a.get_bool("--full"),
        flag_cross: a.get_bool("--cross"),
        flag_output: a.get_str("--output"),
        flag_no_headers: a.get_bool("--no-headers"),
        flag_no_case: a.get_bool("--no-case"),
        flag_nulls: a.get_bool("--nulls"),
        flag_delimiter: a.opt_delim("--delimiter")?,
    };

    let mut state = args.new_io_state()?;
    match (args.flag_left, args.flag_right, args.flag_full, args.flag_cross) {
        (true, false, false, false) => {
            state.write_headers()?;
            state.outer_join(false)
        }
        (false, true, false, false) => {
            state.write_headers()?;
            state.outer_join(true)
        }
        (false, false, true, false) => {
            state.write_headers()?;
            state.full_outer_join()
        }
        (false, false, false, true) => {
            state.write_headers()?;
            state.cross_join()
        }
        (false, false, false, false) => {
            state.write_headers()?;
            state.inner_join()
        }
        _ => Err("Please pick exactly one join operation.".into()),
    }
}

struct IoState<W: Write> {
    wtr: csv::Writer<W>,
    rdr1: csv::Reader<fs::File>,
    sel1: Selection,
    rdr2: csv::Reader<fs::File>,
    sel2: Selection,
    no_headers: bool,
    casei: bool,
    nulls: bool,
}

impl<W: Write> IoState<W> {
    fn write_headers(&mut self) -> CliResult<()> {
        if !self.no_headers {
            let mut headers = self.rdr1.byte_headers()?;
            let h2 = self.rdr2.byte_headers()?;
            headers.extend_from(&h2);
            self.wtr.write_byte_record(&headers)?;
        }
        Ok(())
    }

    fn inner_join(mut self) -> CliResult<()> {
        let validx = ValueIndex::new(&mut self.rdr2, &self.sel2, self.casei, self.nulls)?;
        while let Some(row) = self.rdr1.next_record() {
            let row = row?;
            let key = get_row_key(&self.sel1, &row, self.casei);
            if let Some(rows) = validx.values.get(&key) {
                for &rowi in rows.iter() {
                    let other = &validx.rows[rowi];
                    self.wtr.write_record(row.iter().chain(other.iter()))?;
                }
            }
        }
        self.wtr.flush()?;
        Ok(())
    }

    fn outer_join(mut self, right: bool) -> CliResult<()> {
        if right {
            std::mem::swap(&mut self.rdr1, &mut self.rdr2);
            std::mem::swap(&mut self.sel1, &mut self.sel2);
        }
        let (_, pad2) = self.get_padding()?;
        let validx = ValueIndex::new(&mut self.rdr2, &self.sel2, self.casei, self.nulls)?;
        while let Some(row) = self.rdr1.next_record() {
            let row = row?;
            let key = get_row_key(&self.sel1, &row, self.casei);
            match validx.values.get(&key) {
                None => {
                    if right {
                        self.wtr.write_record(pad2.iter().chain(row.iter()))?;
                    } else {
                        self.wtr.write_record(row.iter().chain(pad2.iter()))?;
                    }
                }
                Some(rows) => {
                    for &rowi in rows.iter() {
                        let other = &validx.rows[rowi];
                        if right {
                            self.wtr.write_record(other.iter().chain(row.iter()))?;
                        } else {
                            self.wtr.write_record(row.iter().chain(other.iter()))?;
                        }
                    }
                }
            }
        }
        self.wtr.flush()?;
        Ok(())
    }

    fn full_outer_join(mut self) -> CliResult<()> {
        let (pad1, pad2) = self.get_padding()?;
        let validx = ValueIndex::new(&mut self.rdr2, &self.sel2, self.casei, self.nulls)?;
        let mut rdr2_written = vec![false; validx.rows.len()];
        while let Some(row1) = self.rdr1.next_record() {
            let row1 = row1?;
            let key = get_row_key(&self.sel1, &row1, self.casei);
            match validx.values.get(&key) {
                None => {
                    self.wtr.write_record(row1.iter().chain(pad2.iter()))?;
                }
                Some(rows) => {
                    for &rowi in rows.iter() {
                        rdr2_written[rowi] = true;
                        let other = &validx.rows[rowi];
                        self.wtr.write_record(row1.iter().chain(other.iter()))?;
                    }
                }
            }
        }
        for (i, &written) in rdr2_written.iter().enumerate() {
            if !written {
                let other = &validx.rows[i];
                self.wtr.write_record(pad1.iter().chain(other.iter()))?;
            }
        }
        self.wtr.flush()?;
        Ok(())
    }

    fn cross_join(mut self) -> CliResult<()> {
        let mut cache: Option<Vec<ByteRecord>> = None;
        while let Some(row1) = self.rdr1.next_record() {
            let row1 = row1?;
            match cache {
                Some(ref rows) => {
                    for row2 in rows.iter() {
                        self.wtr.write_record(row1.iter().chain(row2.iter()))?;
                    }
                }
                None => {
                    let mut rows = vec![];
                    self.rdr2.seek(Position::new())?;
                    let mut row2 = ByteRecord::new();
                    if self.rdr2.has_headers() {
                        self.rdr2.read_byte_record(&mut row2)?;
                    }
                    while self.rdr2.read_byte_record(&mut row2)? {
                        self.wtr.write_record(row1.iter().chain(row2.iter()))?;
                        rows.push(row2.clone());
                    }
                    cache = Some(rows);
                }
            }
        }
        self.wtr.flush()?;
        Ok(())
    }

    fn get_padding(&mut self) -> CliResult<(ByteRecord, ByteRecord)> {
        let len1 = self.rdr1.byte_headers()?.len();
        let len2 = self.rdr2.byte_headers()?.len();
        let mut p1 = ByteRecord::new();
        for _ in 0..len1 {
            p1.push_field(b"");
        }
        let mut p2 = ByteRecord::new();
        for _ in 0..len2 {
            p2.push_field(b"");
        }
        Ok((p1, p2))
    }
}

impl Args {
    fn new_io_state(&self) -> CliResult<IoState<Box<dyn Write>>> {
        let rconf1 = Config::new(&Some(self.arg_input1.clone()))
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
            .select(self.arg_columns1.clone());
        let rconf2 = Config::new(&Some(self.arg_input2.clone()))
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
            .select(self.arg_columns2.clone());

        let mut rdr1 = rconf1.reader_file()?;
        let mut rdr2 = rconf2.reader_file()?;
        let headers1 = rdr1.byte_headers()?;
        let headers2 = rdr2.byte_headers()?;
        let sel1 = rconf1.selection(&headers1)?;
        let sel2 = rconf2.selection(&headers2)?;
        if sel1.len() != sel2.len() {
            return Err(format!(
                "Column selections must have the same number of columns, but found column selections with {} and {} columns.",
                sel1.len(),
                sel2.len()
            )
            .into());
        }
        Ok(IoState {
            wtr: Config::new(&self.flag_output).writer()?,
            rdr1,
            sel1,
            rdr2,
            sel2,
            no_headers: rconf1.no_headers,
            casei: self.flag_no_case,
            nulls: self.flag_nulls,
        })
    }
}

struct ValueIndex {
    values: HashMap<Vec<Vec<u8>>, Vec<usize>>,
    rows: Vec<ByteRecord>,
}

impl ValueIndex {
