use std::cmp;
use std::str;

use crate::cmd::get_args;
use crate::config::Config;
use crate::docopt;
use crate::select::SelectColumns;
use crate::CliResult;

const USAGE: &str = include_str!("../usage/sort.txt");

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = get_args(USAGE, argv)?;
    let arg_input = a.get_str("<input>");
    let flag_select =
        SelectColumns::parse(&a.string("--select")).map_err(docopt::Error::Deserialize)?;
    let flag_numeric = a.get_bool("--numeric");
    let flag_reverse = a.get_bool("--reverse");
    let flag_output = a.get_str("--output");
    let flag_no_headers = a.get_bool("--no-headers");
    let flag_delimiter = a.opt_delim("--delimiter")?;

    let rconfig = Config::new(&arg_input)
        .delimiter(flag_delimiter)
        .no_headers(flag_no_headers)
        .select(flag_select);

    let mut rdr = rconfig.reader()?;
    let headers = rdr.byte_headers()?;
    let sel = rconfig.selection(&headers)?;

    let mut all = rdr.records().collect::<Result<Vec<_>, _>>()?;
    match (flag_numeric, flag_reverse) {
        (false, false) => all.sort_by(|r1, r2| iter_cmp(sel.select(r1), sel.select(r2))),
        (true, false) => all.sort_by(|r1, r2| iter_cmp_num(sel.select(r1), sel.select(r2))),
        (false, true) => all.sort_by(|r1, r2| iter_cmp(sel.select(r2), sel.select(r1))),
        (true, true) => all.sort_by(|r1, r2| iter_cmp_num(sel.select(r2), sel.select(r1))),
    }

    let mut wtr = Config::new(&flag_output).writer()?;
    rconfig.write_headers(&mut rdr, &mut wtr)?;
    for r in all.into_iter() {
        wtr.write_byte_record(&r)?;
    }
    wtr.flush()?;
    Ok(())
}

fn iter_cmp<'a, L, R>(mut a: L, mut b: R) -> cmp::Ordering
where
    L: Iterator<Item = &'a [u8]>,
    R: Iterator<Item = &'a [u8]>,
{
    loop {
        match (a.next(), b.next()) {
            (None, None) => return cmp::Ordering::Equal,
            (None, _) => return cmp::Ordering::Less,
            (_, None) => return cmp::Ordering::Greater,
            (Some(x), Some(y)) => match x.cmp(y) {
                cmp::Ordering::Equal => (),
                non_eq => return non_eq,
            },
        }
    }
}

fn iter_cmp_num<'a, L, R>(mut a: L, mut b: R) -> cmp::Ordering
where
    L: Iterator<Item = &'a [u8]>,
    R: Iterator<Item = &'a [u8]>,
{
    loop {
        match (next_num(&mut a), next_num(&mut b)) {
            (None, None) => return cmp::Ordering::Equal,
            (None, _) => return cmp::Ordering::Less,
            (_, None) => return cmp::Ordering::Greater,
            (Some(x), Some(y)) => match compare_num(x, y) {
                cmp::Ordering::Equal => (),
                non_eq => return non_eq,
            },
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Number {
    Int(i64),
    Float(f64),
}

fn compare_num(n1: Number, n2: Number) -> cmp::Ordering {
    use self::Number::{Float, Int};
    match (n1, n2) {
        (Int(i1), Int(i2)) => i1.cmp(&i2),
        (Int(i1), Float(f2)) => compare_float(i1 as f64, f2),
        (Float(f1), Int(i2)) => compare_float(f1, i2 as f64),
        (Float(f1), Float(f2)) => compare_float(f1, f2),
    }
}

fn compare_float(f1: f64, f2: f64) -> cmp::Ordering {
    f1.partial_cmp(&f2).unwrap_or(cmp::Ordering::Equal)
}

fn next_num<'a, X>(xs: &mut X) -> Option<Number>
where
    X: Iterator<Item = &'a [u8]>,
{
    match xs.next() {
        Some(bytes) => {
            let s = str::from_utf8(bytes).ok();
            if let Some(i) = s.and_then(|s| s.parse::<i64>().ok()) {
                Some(Number::Int(i))
            } else if let Some(f) = s.and_then(|s| s.parse::<f64>().ok()) {
                Some(Number::Float(f))
            } else {
                None
            }
        }
        None => None,
    }
}
