    let args = Args {
        arg_input,
        arg_outdir,
        flag_size,
        flag_jobs,
        flag_filename,
        flag_no_headers,
        flag_delimiter,
    };
    let _ = args.flag_jobs;
    if args.flag_size == 0 {
        return Err("--size must be greater than 0.".into());
    }
    fs::create_dir_all(&args.arg_outdir)?;

    match args.rconfig().indexed()? {
        Some(idx) => args.parallel_split(idx),
        None => args.sequential_split(),
    }
}

impl Args {
    fn sequential_split(&self) -> CliResult<()> {
        let rconfig = self.rconfig();
        let mut rdr = rconfig.reader()?;
        let headers = rdr.byte_headers()?;

        let mut wtr = self.new_writer(&headers, 0)?;
        let mut i = 0;
        let mut row = ByteRecord::new();
        while rdr.read_byte_record(&mut row)? {
            if i > 0 && i % self.flag_size == 0 {
                wtr.flush()?;
                wtr = self.new_writer(&headers, i)?;
            }
            wtr.write_byte_record(&row)?;
            i += 1;
        }
        wtr.flush()?;
        Ok(())
    }

    fn parallel_split(&self, idx: Indexed) -> CliResult<()> {
        let nchunks = util::num_of_chunks(idx.count() as usize, self.flag_size);
        for i in 0..nchunks {
            let conf = self.rconfig();
            let mut idx = match conf.indexed()? {
                Some(idx) => idx,
                None => return Err("index disappeared".into()),
            };
            let headers = idx.rdr.byte_headers()?;
            let mut wtr = self.new_writer(&headers, i * self.flag_size)?;
            idx.seek((i * self.flag_size) as u64)?;
            let mut n = 0;
            while n < self.flag_size {
                match idx.rdr.next_record() {
                    None => break,
                    Some(row) => {
                        wtr.write_byte_record(&row?)?;
                        n += 1;
                    }
                }
            }
            wtr.flush()?;
        }
        Ok(())
    }

    fn new_writer(
        &self,
        headers: &ByteRecord,
        start: usize,
    ) -> CliResult<csv::Writer<Box<dyn Write>>> {
        let dir = Path::new(&self.arg_outdir);
        let path = dir.join(self.flag_filename.filename(&format!("{}", start)));
        let spath = Some(path.display().to_string());
        let mut wtr = Config::new(&spath).writer()?;
        if !self.rconfig().no_headers {
            wtr.write_byte_record(headers)?;
        }
        Ok(wtr)
    }

    fn rconfig(&self) -> Config {
        Config::new(&self.arg_input)
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
    }
}
