use std::cmp::Ordering;
use std::io::Read;
use std::str;

use crate::cmd::get_args;
use crate::config::Config;
use crate::csv::{self, ByteRecord};
use crate::docopt;
use crate::index::Indexed;
use crate::select::{SelectColumns, Selection};
use crate::util;
use crate::CliResult;

const USAGE: &str = include_str!("../usage/stats.txt");

#[derive(Clone)]
struct Args {
    arg_input: Option<String>,
    flag_select: SelectColumns,
    flag_everything: bool,
    flag_mode: bool,
    flag_cardinality: bool,
    flag_median: bool,
    flag_nulls: bool,
    flag_jobs: usize,
    flag_output: Option<String>,
    flag_no_headers: bool,
    flag_delimiter: Option<u8>,
}

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = get_args(USAGE, argv)?;
    let arg_input = a.get_str("<input>");
    let flag_select =
        SelectColumns::parse(&a.string("--select")).map_err(docopt::Error::Deserialize)?;
    let flag_everything = a.get_bool("--everything");
    let flag_mode = a.get_bool("--mode");
    let flag_cardinality = a.get_bool("--cardinality");
    let flag_median = a.get_bool("--median");
    let flag_nulls = a.get_bool("--nulls");
    let flag_jobs = a.usize("--jobs")?;
    let flag_output = a.get_str("--output");
    let flag_no_headers = a.get_bool("--no-headers");
    let flag_delimiter = a.opt_delim("--delimiter")?;
    let args = Args {
        arg_input,
        flag_select,
        flag_everything,
        flag_mode,
        flag_cardinality,
        flag_median,
        flag_nulls,
        flag_jobs,
        flag_output,
        flag_no_headers,
        flag_delimiter,
    };

    let mut wtr = Config::new(&args.flag_output).writer()?;
    let (headers, stats) = match args.rconfig().indexed()? {
        None => args.sequential_stats(),
        Some(idx) => {
            if args.njobs() > 1 {
                args.parallel_stats(idx)
            } else {
                args.sequential_stats()
            }
        }
    }?;
    let stats: Vec<Vec<String>> = stats.into_iter().map(|mut s| s.to_record()).collect();

    let sh = args.stat_headers();
    wtr.write_record(sh.iter().map(|s| s.as_bytes()))?;
    for (i, (header, stat)) in headers.iter().zip(stats.into_iter()).enumerate() {
        let header = if args.flag_no_headers {
            i.to_string().into_bytes()
        } else {
            header.to_vec()
        };
        wtr.write_record(
            std::iter::once(&header[..]).chain(stat.iter().map(|f| f.as_bytes())),
        )?;
    }
    wtr.flush()?;
    Ok(())
}

impl Args {
    fn sequential_stats(&self) -> CliResult<(ByteRecord, Vec<Stats>)> {
        let mut rdr = self.rconfig().reader()?;
        let (headers, sel) = self.sel_headers(&mut rdr)?;
        let stats = self.compute(&sel, rdr.records())?;
        Ok((headers, stats))
    }

    fn parallel_stats(&self, idx: Indexed) -> CliResult<(ByteRecord, Vec<Stats>)> {
        if idx.count() == 0 {
            return self.sequential_stats();
        }
        let mut rdr = self.rconfig().reader()?;
        let (headers, sel) = self.sel_headers(&mut rdr)?;
        let count = idx.count() as usize;
        let chunk_size = util::chunk_size(count, self.njobs());
        let nchunks = util::num_of_chunks(count, chunk_size);
        let mut acc: Option<Vec<Stats>> = None;
        for i in 0..nchunks {
            let mut idx = match self.rconfig().indexed()? {
                Some(idx) => idx,
                None => return Err("index disappeared".into()),
            };
            idx.seek((i * chunk_size) as u64)?;
            let it = idx.rdr.records().take(chunk_size);
            let stats = self.compute(&sel, it)?;
            acc = Some(match acc {
                None => stats,
                Some(mut a) => {
                    for (x, y) in a.iter_mut().zip(stats.into_iter()) {
                        x.merge(y);
                    }
                    a
                }
            });
        }
        Ok((headers, acc.unwrap_or_default()))
    }

    fn compute<I>(&self, sel: &Selection, it: I) -> CliResult<Vec<Stats>>
    where
        I: Iterator<Item = csv::Result<ByteRecord>>,
    {
        let mut stats = self.new_stats(sel.len());
        for row in it {
            let row = row?;
            for (i, field) in sel.select(&row).enumerate() {
                stats[i].add(field);
            }
        }
        Ok(stats)
    }

    fn sel_headers<R: Read>(&self, rdr: &mut csv::Reader<R>) -> CliResult<(ByteRecord, Selection)> {
        let headers = rdr.byte_headers()?;
        let sel = self.rconfig().selection(&headers)?;
        Ok((ByteRecord::from_fields(sel.select(&headers)), sel))
    }

    fn rconfig(&self) -> Config {
        Config::new(&self.arg_input)
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
            .select(self.flag_select.clone())
    }

    fn njobs(&self) -> usize {
        if self.flag_jobs == 0 {
            util::num_cpus()
        } else {
            self.flag_jobs
        }
    }

    fn new_stats(&self, record_len: usize) -> Vec<Stats> {
        let which = WhichStats {
            include_nulls: self.flag_nulls,
            sum: true,
            range: true,
            dist: true,
            cardinality: self.flag_cardinality || self.flag_everything,
            median: self.flag_median || self.flag_everything,
            mode: self.flag_mode || self.flag_everything,
        };
        (0..record_len).map(|_| Stats::new(which)).collect()
    }

    fn stat_headers(&self) -> Vec<String> {
        let mut fields = vec![
            "field", "type", "sum", "min", "max", "min_length", "max_length", "mean", "stddev",
        ];
        let all = self.flag_everything;
        if self.flag_median || all {
            fields.push("median");
        }
        if self.flag_mode || all {
            fields.push("mode");
        }
        if self.flag_cardinality || all {
            fields.push("cardinality");
        }
        fields.into_iter().map(|s| s.to_owned()).collect()
    }
}

#[derive(Clone, Copy, PartialEq)]
struct WhichStats {
    include_nulls: bool,
    sum: bool,
    range: bool,
    dist: bool,
    cardinality: bool,
    median: bool,
    mode: bool,
}

#[derive(Clone)]
struct Stats {
    typ: FieldType,
    sum: Option<TypedSum>,
    minmax: Option<TypedMinMax>,
    online: Option<OnlineStats>,
    mode: Option<Unsorted<Vec<u8>>>,
    median: Option<Unsorted<f64>>,
    which: WhichStats,
}

fn parse_f64(s: &[u8]) -> Option<f64> {
    str::from_utf8(s).ok().and_then(|s| s.parse::<f64>().ok())
}

fn parse_i64(s: &[u8]) -> Option<i64> {
    str::from_utf8(s).ok().and_then(|s| s.parse::<i64>().ok())
}

impl Stats {
    fn new(which: WhichStats) -> Stats {
        let (mut sum, mut minmax, mut online, mut mode, mut median) = (None, None, None, None, None);
        if which.sum {
            sum = Some(TypedSum::default());
        }
        if which.range {
            minmax = Some(TypedMinMax::default());
        }
        if which.dist {
            online = Some(OnlineStats::default());
        }
        if which.mode || which.cardinality {
            mode = Some(Unsorted::default());
        }
        if which.median {
            median = Some(Unsorted::default());
        }
        Stats { typ: FieldType::TNull, sum, minmax, online, mode, median, which }
    }

    fn add(&mut self, sample: &[u8]) {
        let sample_type = FieldType::from_sample(sample);
        self.typ.merge(sample_type);

        let t = self.typ;
        if let Some(v) = self.sum.as_mut() {
            v.add(t, sample);
        }
        if let Some(v) = self.minmax.as_mut() {
            v.add(t, sample);
        }
        if let Some(v) = self.mode.as_mut() {
            v.add(sample.to_vec());
        }
        match self.typ {
            FieldType::TUnknown => {}
            FieldType::TNull => {
                if self.which.include_nulls {
                    if let Some(v) = self.online.as_mut() {
                        v.add_null();
                    }
                }
            }
            FieldType::TUnicode => {}
            FieldType::TFloat | FieldType::TInteger => {
                if sample_type.is_null() {
                    if self.which.include_nulls {
                        if let Some(v) = self.online.as_mut() {
                            v.add_null();
                        }
                    }
                } else {
                    let n = parse_f64(sample).unwrap();
                    if let Some(v) = self.median.as_mut() {
                        v.add(n);
                    }
                    if let Some(v) = self.online.as_mut() {
                        v.add(n);
                    }
                }
            }
        }
    }

    fn merge(&mut self, other: Stats) {
        self.typ.merge(other.typ);
        merge_opt(&mut self.sum, other.sum, |a, b| a.merge(b));
        merge_opt(&mut self.minmax, other.minmax, |a, b| a.merge(b));
        merge_opt(&mut self.online, other.online, |a, b| a.merge(b));
        merge_opt(&mut self.mode, other.mode, |a, b| a.merge(b));
        merge_opt(&mut self.median, other.median, |a, b| a.merge(b));
    }

    fn to_record(&mut self) -> Vec<String> {
        let typ = self.typ;
        let mut pieces = vec![];
        let empty = String::new;

        pieces.push(self.typ.to_string());
        match self.sum.as_ref().and_then(|sum| sum.show(typ)) {
            Some(sum) => pieces.push(sum),
            None => pieces.push(empty()),
        }
        match self.minmax.as_ref().and_then(|mm| mm.show(typ)) {
            Some(mm) => {
                pieces.push(mm.0);
                pieces.push(mm.1);
            }
            None => {
                pieces.push(empty());
                pieces.push(empty());
            }
        }
        match self.minmax.as_ref().and_then(|mm| mm.len_range()) {
            Some(mm) => {
                pieces.push(mm.0);
                pieces.push(mm.1);
            }
            None => {
                pieces.push(empty());
                pieces.push(empty());
            }
        }
        if !self.typ.is_number() {
            pieces.push(empty());
            pieces.push(empty());
        } else {
            match self.online {
                Some(ref v) => {
                    pieces.push(v.mean().to_string());
                    pieces.push(v.stddev().to_string());
                }
                None => {
                    pieces.push(empty());
                    pieces.push(empty());
                }
            }
        }
        match self.median.as_mut().and_then(|v| v.median()) {
            None => {
                if self.which.median {
                    pieces.push(empty());
                }
            }
            Some(v) => pieces.push(v.to_string()),
        }
        match self.mode.as_mut() {
            None => {
                if self.which.mode {
                    pieces.push(empty());
                }
                if self.which.cardinality {
                    pieces.push(empty());
                }
            }
            Some(v) => {
                if self.which.mode {
                    pieces.push(
                        v.mode()
                            .map_or("N/A".to_owned(), |s| String::from_utf8_lossy(&s).into_owned()),
                    );
                }
                if self.which.cardinality {
                    pieces.push(v.cardinality().to_string());
                }
            }
        }
        pieces
    }
}

fn merge_opt<T, F: FnOnce(&mut T, T)>(a: &mut Option<T>, b: Option<T>, f: F) {
    match (a.as_mut(), b) {
        (Some(x), Some(y)) => f(x, y),
        (None, Some(y)) => *a = Some(y),
        _ => {}
    }
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum FieldType {
    TUnknown,
    TNull,
    TUnicode,
    TFloat,
    TInteger,
}

impl FieldType {
    fn from_sample(sample: &[u8]) -> FieldType {
        if sample.is_empty() {
            return FieldType::TNull;
        }
        let string = match str::from_utf8(sample) {
            Err(_) => return FieldType::TUnknown,
            Ok(s) => s,
        };
        if string.parse::<i64>().is_ok() {
            return FieldType::TInteger;
        }
        if string.parse::<f64>().is_ok() {
            return FieldType::TFloat;
        }
        FieldType::TUnicode
    }

    fn is_number(&self) -> bool {
        *self == FieldType::TFloat || *self == FieldType::TInteger
    }

    fn is_null(&self) -> bool {
        *self == FieldType::TNull
    }

    fn merge(&mut self, other: FieldType) {
        use self::FieldType::*;
        *self = match (*self, other) {
            (TUnicode, TUnicode) => TUnicode,
            (TFloat, TFloat) => TFloat,
            (TInteger, TInteger) => TInteger,
            (TNull, any) | (any, TNull) => any,
            (TUnknown, _) | (_, TUnknown) => TUnknown,
            (TFloat, TInteger) | (TInteger, TFloat) => TFloat,
            (TUnicode, TFloat) | (TFloat, TUnicode) => TUnicode,
            (TUnicode, TInteger) | (TInteger, TUnicode) => TUnicode,
        };
    }
}

impl std::fmt::Display for FieldType {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        use self::FieldType::*;
        match *self {
            TUnknown => write!(f, "Unknown"),
            TNull => write!(f, "NULL"),
            TUnicode => write!(f, "Unicode"),
            TFloat => write!(f, "Float"),
            TInteger => write!(f, "Integer"),
        }
    }
}

#[derive(Clone, Default)]
struct TypedSum {
    integer: i64,
    float: Option<f64>,
}

impl TypedSum {
    fn add(&mut self, typ: FieldType, sample: &[u8]) {
        if sample.is_empty() {
            return;
        }
        match typ {
            FieldType::TFloat => {
                let float = parse_f64(sample).unwrap();
                match self.float {
                    None => self.float = Some((self.integer as f64) + float),
                    Some(ref mut f) => *f += float,
                }
            }
            FieldType::TInteger => {
                if let Some(ref mut float) = self.float {
                    *float += parse_f64(sample).unwrap();
                } else {
                    self.integer = self.integer.wrapping_add(parse_i64(sample).unwrap());
                }
            }
            _ => {}
        }
    }

    fn show(&self, typ: FieldType) -> Option<String> {
        match typ {
            FieldType::TNull | FieldType::TUnicode | FieldType::TUnknown => None,
            FieldType::TInteger => Some(self.integer.to_string()),
            FieldType::TFloat => Some(self.float.unwrap_or(0.0).to_string()),
        }
    }

    fn merge(&mut self, other: TypedSum) {
        match (self.float, other.float) {
            (Some(f1), Some(f2)) => self.float = Some(f1 + f2),
            (Some(f1), None) => self.float = Some(f1 + (other.integer as f64)),
            (None, Some(f2)) => self.float = Some((self.integer as f64) + f2),
            (None, None) => self.integer = self.integer.wrapping_add(other.integer),
        }
    }
}

#[derive(Clone)]
struct MinMax<T> {
    len: u64,
    min: Option<T>,
    max: Option<T>,
}

impl<T> Default for MinMax<T> {
    fn default() -> MinMax<T> {
        MinMax { len: 0, min: None, max: None }
    }
}

impl<T: PartialOrd + Clone> MinMax<T> {
    fn add(&mut self, sample: T) {
        match self.min {
            None => self.min = Some(sample.clone()),
            Some(ref mut v) if sample < *v => *v = sample.clone(),
            _ => {}
        }
        match self.max {
            None => self.max = Some(sample),
            Some(ref mut v) if sample > *v => *v = sample,
            _ => {}
        }
        self.len += 1;
    }

    fn merge(&mut self, v: MinMax<T>) {
        self.len += v.len;
        if self.min.is_none() || (v.min.is_some() && opt_lt(&v.min, &self.min)) {
            self.min = v.min;
        }
        if self.max.is_none() || (v.max.is_some() && opt_lt(&self.max, &v.max)) {
            self.max = v.max;
        }
    }
}

fn opt_lt<T: PartialOrd>(a: &Option<T>, b: &Option<T>) -> bool {
    a < b
}

#[derive(Clone, Default)]
struct TypedMinMax {
    strings: MinMax<Vec<u8>>,
    str_len: MinMax<usize>,
    integers: MinMax<i64>,
    floats: MinMax<f64>,
}

impl TypedMinMax {
    fn add(&mut self, typ: FieldType, sample: &[u8]) {
        self.str_len.add(sample.len());
        if sample.is_empty() {
            return;
        }
        self.strings.add(sample.to_vec());
        match typ {
            FieldType::TUnicode | FieldType::TUnknown | FieldType::TNull => {}
            FieldType::TFloat => {
                let n = parse_f64(sample).unwrap();
                self.floats.add(n);
                self.integers.add(n as i64);
            }
            FieldType::TInteger => {
                let n = parse_i64(sample).unwrap();
                self.integers.add(n);
                self.floats.add(n as f64);
            }
        }
    }

    fn len_range(&self) -> Option<(String, String)> {
        match (self.str_len.min, self.str_len.max) {
            (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
            _ => None,
        }
    }

    fn show(&self, typ: FieldType) -> Option<(String, String)> {
        match typ {
            FieldType::TNull => None,
            FieldType::TUnicode | FieldType::TUnknown => {
                match (self.strings.min.as_ref(), self.strings.max.as_ref()) {
                    (Some(min), Some(max)) => Some((
                        String::from_utf8_lossy(min).into_owned(),
                        String::from_utf8_lossy(max).into_owned(),
                    )),
                    _ => None,
                }
            }
            FieldType::TInteger => match (self.integers.min, self.integers.max) {
                (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
                _ => None,
            },
            FieldType::TFloat => match (self.floats.min, self.floats.max) {
                (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
                _ => None,
            },
        }
    }

    fn merge(&mut self, other: TypedMinMax) {
        self.strings.merge(other.strings);
        self.str_len.merge(other.str_len);
        self.integers.merge(other.integers);
        self.floats.merge(other.floats);
    }
}

#[derive(Clone, Copy, Default)]
struct OnlineStats {
    size: u64,
    mean: f64,
    variance: f64,
}

impl OnlineStats {
    fn mean(&self) -> f64 {
        self.mean
    }

    fn stddev(&self) -> f64 {
        self.variance.sqrt()
    }

    fn add(&mut self, sample: f64) {
        let oldmean = self.mean;
        let prevq = self.variance * (self.size as f64);
        self.size += 1;
        self.mean += (sample - oldmean) / (self.size as f64);
        self.variance = (prevq + (sample - oldmean) * (sample - self.mean)) / (self.size as f64);
    }

    fn add_null(&mut self) {
        self.add(0.0);
    }

    fn merge(&mut self, v: OnlineStats) {
        let (s1, s2) = (self.size as f64, v.size as f64);
        let meandiffsq = (self.mean - v.mean) * (self.mean - v.mean);
        let mean = ((s1 * self.mean) + (s2 * v.mean)) / (s1 + s2);
        let var = (((s1 * self.variance) + (s2 * v.variance)) / (s1 + s2))
            + ((s1 * s2 * meandiffsq) / ((s1 + s2) * (s1 + s2)));
        self.size += v.size;
        self.mean = mean;
        self.variance = var;
    }
}

#[derive(Clone)]
struct Unsorted<T> {
    sorted: bool,
    data: Vec<T>,
}

impl<T> Default for Unsorted<T> {
    fn default() -> Unsorted<T> {
        Unsorted { sorted: true, data: vec![] }
    }
}

impl<T: PartialOrd + Clone> Unsorted<T> {
    fn add(&mut self, v: T) {
        self.sorted = false;
        self.data.push(v);
    }

    fn sort(&mut self) {
        if !self.sorted {
            self.data
                .sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
            self.sorted = true;
        }
    }

    fn merge(&mut self, v: Unsorted<T>) {
        self.sorted = false;
        self.data.extend(v.data);
    }

    fn mode(&mut self) -> Option<T> {
        self.sort();
        let (mut mode, mut next): (Option<&T>, Option<&T>) = (None, None);
        let (mut mode_count, mut next_count) = (0usize, 0usize);
        for x in self.data.iter() {
            if mode.map(|y| y == x).unwrap_or(false) {
                mode_count += 1;
            } else if next.map(|y| y == x).unwrap_or(false) {
                next_count += 1;
            } else {
                next = Some(x);
                next_count = 0;
            }
            if next_count > mode_count {
                mode = next;
                mode_count = next_count;
                next = None;
                next_count = 0;
            }
        }
        mode.cloned()
    }

    fn cardinality(&mut self) -> usize {
        self.sort();
        let mut count = 0;
        let mut last: Option<&T> = None;
        for x in self.data.iter() {
            if last.map(|l| l != x).unwrap_or(true) {
                count += 1;
            }
            last = Some(x);
        }
        count
    }
}

impl Unsorted<f64> {
    fn median(&mut self) -> Option<f64> {
        self.sort();
        let data = &self.data;
        Some(match data.len() {
            0 => return None,
            1 => data[0],
            len if len % 2 == 0 => {
                let v1 = data[(len / 2) - 1];
                let v2 = data[len / 2];
                (v1 + v2) / 2.0
            }
            len => data[len / 2],
        })
    }
}
