fn merge_opt<T, F: FnOnce(&mut T, T)>(a: &mut Option<T>, b: Option<T>, f: F) {
    match (a.as_mut(), b) {
        (Some(x), Some(y)) => f(x, y),
        (None, Some(y)) => *a = Some(y),
        _ => {}
    }
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum FieldType {
    TUnknown,
    TNull,
    TUnicode,
    TFloat,
    TInteger,
}

impl FieldType {
    fn from_sample(sample: &[u8]) -> FieldType {
        if sample.is_empty() {
            return FieldType::TNull;
        }
        let string = match str::from_utf8(sample) {
            Err(_) => return FieldType::TUnknown,
            Ok(s) => s,
        };
        if string.parse::<i64>().is_ok() {
            return FieldType::TInteger;
        }
        if string.parse::<f64>().is_ok() {
            return FieldType::TFloat;
        }
        FieldType::TUnicode
    }

    fn is_number(&self) -> bool {
        *self == FieldType::TFloat || *self == FieldType::TInteger
    }

    fn is_null(&self) -> bool {
        *self == FieldType::TNull
    }

    fn merge(&mut self, other: FieldType) {
        use self::FieldType::*;
        *self = match (*self, other) {
            (TUnicode, TUnicode) => TUnicode,
            (TFloat, TFloat) => TFloat,
            (TInteger, TInteger) => TInteger,
            (TNull, any) | (any, TNull) => any,
            (TUnknown, _) | (_, TUnknown) => TUnknown,
            (TFloat, TInteger) | (TInteger, TFloat) => TFloat,
            (TUnicode, TFloat) | (TFloat, TUnicode) => TUnicode,
            (TUnicode, TInteger) | (TInteger, TUnicode) => TUnicode,
        };
    }
}

impl std::fmt::Display for FieldType {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        use self::FieldType::*;
        match *self {
            TUnknown => write!(f, "Unknown"),
            TNull => write!(f, "NULL"),
            TUnicode => write!(f, "Unicode"),
            TFloat => write!(f, "Float"),
            TInteger => write!(f, "Integer"),
        }
    }
}

#[derive(Clone, Default)]
struct TypedSum {
    integer: i64,
    float: Option<f64>,
}

impl TypedSum {
    fn add(&mut self, typ: FieldType, sample: &[u8]) {
        if sample.is_empty() {
            return;
        }
        match typ {
            FieldType::TFloat => {
                let float = parse_f64(sample).unwrap();
                match self.float {
                    None => self.float = Some((self.integer as f64) + float),
                    Some(ref mut f) => *f += float,
                }
            }
            FieldType::TInteger => {
                if let Some(ref mut float) = self.float {
                    *float += parse_f64(sample).unwrap();
                } else {
                    self.integer = self.integer.wrapping_add(parse_i64(sample).unwrap());
                }
            }
            _ => {}
        }
    }

    fn show(&self, typ: FieldType) -> Option<String> {
        match typ {
            FieldType::TNull | FieldType::TUnicode | FieldType::TUnknown => None,
            FieldType::TInteger => Some(self.integer.to_string()),
            FieldType::TFloat => Some(self.float.unwrap_or(0.0).to_string()),
        }
    }

    fn merge(&mut self, other: TypedSum) {
        match (self.float, other.float) {
            (Some(f1), Some(f2)) => self.float = Some(f1 + f2),
            (Some(f1), None) => self.float = Some(f1 + (other.integer as f64)),
            (None, Some(f2)) => self.float = Some((self.integer as f64) + f2),
            (None, None) => self.integer = self.integer.wrapping_add(other.integer),
        }
    }
}

#[derive(Clone)]
struct MinMax<T> {
    len: u64,
    min: Option<T>,
    max: Option<T>,
}

impl<T> Default for MinMax<T> {
    fn default() -> MinMax<T> {
        MinMax { len: 0, min: None, max: None }
    }
}

impl<T: PartialOrd + Clone> MinMax<T> {
    fn add(&mut self, sample: T) {
        match self.min {
            None => self.min = Some(sample.clone()),
            Some(ref mut v) if sample < *v => *v = sample.clone(),
            _ => {}
        }
        match self.max {
            None => self.max = Some(sample),
            Some(ref mut v) if sample > *v => *v = sample,
            _ => {}
        }
        self.len += 1;
    }

    fn merge(&mut self, v: MinMax<T>) {
        self.len += v.len;
        if self.min.is_none() || (v.min.is_some() && opt_lt(&v.min, &self.min)) {
            self.min = v.min;
        }
        if self.max.is_none() || (v.max.is_some() && opt_lt(&self.max, &v.max)) {
            self.max = v.max;
        }
    }
}

fn opt_lt<T: PartialOrd>(a: &Option<T>, b: &Option<T>) -> bool {
    a < b
}

#[derive(Clone, Default)]
struct TypedMinMax {
    strings: MinMax<Vec<u8>>,
    str_len: MinMax<usize>,
    integers: MinMax<i64>,
    floats: MinMax<f64>,
}

impl TypedMinMax {
    fn add(&mut self, typ: FieldType, sample: &[u8]) {
        self.str_len.add(sample.len());
        if sample.is_empty() {
            return;
        }
        self.strings.add(sample.to_vec());
        match typ {
            FieldType::TUnicode | FieldType::TUnknown | FieldType::TNull => {}
            FieldType::TFloat => {
                let n = parse_f64(sample).unwrap();
                self.floats.add(n);
                self.integers.add(n as i64);
            }
            FieldType::TInteger => {
                let n = parse_i64(sample).unwrap();
                self.integers.add(n);
                self.floats.add(n as f64);
            }
        }
    }

    fn len_range(&self) -> Option<(String, String)> {
        match (self.str_len.min, self.str_len.max) {
            (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
            _ => None,
        }
    }

    fn show(&self, typ: FieldType) -> Option<(String, String)> {
        match typ {
            FieldType::TNull => None,
            FieldType::TUnicode | FieldType::TUnknown => {
                match (self.strings.min.as_ref(), self.strings.max.as_ref()) {
                    (Some(min), Some(max)) => Some((
                        String::from_utf8_lossy(min).into_owned(),
                        String::from_utf8_lossy(max).into_owned(),
                    )),
                    _ => None,
                }
            }
            FieldType::TInteger => match (self.integers.min, self.integers.max) {
                (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
                _ => None,
            },
            FieldType::TFloat => match (self.floats.min, self.floats.max) {
                (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
                _ => None,
            },
        }
    }

    fn merge(&mut self, other: TypedMinMax) {
        self.strings.merge(other.strings);
        self.str_len.merge(other.str_len);
        self.integers.merge(other.integers);
        self.floats.merge(other.floats);
    }
}

#[derive(Clone, Copy, Default)]
struct OnlineStats {
    size: u64,
    mean: f64,
    variance: f64,
}

impl OnlineStats {
    fn mean(&self) -> f64 {
        self.mean
    }

    fn stddev(&self) -> f64 {
        self.variance.sqrt()
    }

    fn add(&mut self, sample: f64) {
        let oldmean = self.mean;
        let prevq = self.variance * (self.size as f64);
        self.size += 1;
        self.mean += (sample - oldmean) / (self.size as f64);
        self.variance = (prevq + (sample - oldmean) * (sample - self.mean)) / (self.size as f64);
    }

    fn add_null(&mut self) {
        self.add(0.0);
    }

    fn merge(&mut self, v: OnlineStats) {
        let (s1, s2) = (self.size as f64, v.size as f64);
        let meandiffsq = (self.mean - v.mean) * (self.mean - v.mean);
        let mean = ((s1 * self.mean) + (s2 * v.mean)) / (s1 + s2);
        let var = (((s1 * self.variance) + (s2 * v.variance)) / (s1 + s2))
            + ((s1 * s2 * meandiffsq) / ((s1 + s2) * (s1 + s2)));
        self.size += v.size;
        self.mean = mean;
        self.variance = var;
    }
}

#[derive(Clone)]
struct Unsorted<T> {
    sorted: bool,
    data: Vec<T>,
}

impl<T> Default for Unsorted<T> {
    fn default() -> Unsorted<T> {
        Unsorted { sorted: true, data: vec![] }
    }
}

impl<T: PartialOrd + Clone> Unsorted<T> {
    fn add(&mut self, v: T) {
        self.sorted = false;
        self.data.push(v);
    }

    fn sort(&mut self) {
        if !self.sorted {
            self.data
                .sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
            self.sorted = true;
        }
    }

    fn merge(&mut self, v: Unsorted<T>) {
        self.sorted = false;
        self.data.extend(v.data);
    }

    fn mode(&mut self) -> Option<T> {
        self.sort();
        let (mut mode, mut next): (Option<&T>, Option<&T>) = (None, None);
        let (mut mode_count, mut next_count) = (0usize, 0usize);
        for x in self.data.iter() {
            if mode.map(|y| y == x).unwrap_or(false) {
                mode_count += 1;
            } else if next.map(|y| y == x).unwrap_or(false) {
                next_count += 1;
            } else {
                next = Some(x);
                next_count = 0;
            }
            if next_count > mode_count {
                mode = next;
                mode_count = next_count;
                next = None;
                next_count = 0;
            }
        }
        mode.cloned()
    }

    fn cardinality(&mut self) -> usize {
        self.sort();
        let mut count = 0;
        let mut last: Option<&T> = None;
        for x in self.data.iter() {
            if last.map(|l| l != x).unwrap_or(true) {
                count += 1;
            }
            last = Some(x);
        }
        count
    }
}

impl Unsorted<f64> {
    fn median(&mut self) -> Option<f64> {
        self.sort();
        let data = &self.data;
        Some(match data.len() {
            0 => return None,
            1 => data[0],
            len if len % 2 == 0 => {
                let v1 = data[(len / 2) - 1];
                let v2 = data[len / 2];
                (v1 + v2) / 2.0
            }
            len => data[len / 2],
        })
    }
}
