use regex_syntax::ast::{self, Ast};

#[derive(Clone, Copy)]
struct Flags {
    case_insensitive: bool,
    unicode: bool,
    ignore_whitespace: bool,
}

fn apply_flags(f: &mut Flags, flags: &ast::Flags) {
    if let Some(v) = flags.flag_state(ast::Flag::CaseInsensitive) {
        f.case_insensitive = v;
    }
    if let Some(v) = flags.flag_state(ast::Flag::Unicode) {
        f.unicode = v;
    }
    if let Some(v) = flags.flag_state(ast::Flag::IgnoreWhitespace) {
        f.ignore_whitespace = v;
    }
}

/// Finds the first bracketed class that translates to an empty class.
fn find_empty_class(pattern: &str, node: &Ast, flags: &mut Flags) -> Option<ast::Span> {
    match *node {
        Ast::Flags(ref sf) => {
            apply_flags(flags, &sf.flags);
            None
        }
        Ast::ClassBracketed(ref c) => {
            let text = &pattern[c.span.start.offset..c.span.end.offset];
            let hir = regex_syntax::ParserBuilder::new()
                .utf8(false)
                .unicode(flags.unicode)
                .case_insensitive(flags.case_insensitive)
                .ignore_whitespace(flags.ignore_whitespace)
                .build()
                .parse(text);
            if let Ok(h) = hir {
                if let regex_syntax::hir::HirKind::Class(ref cls) = *h.kind() {
                    let empty = match *cls {
                        regex_syntax::hir::Class::Unicode(ref u) => u.ranges().is_empty(),
                        regex_syntax::hir::Class::Bytes(ref b) => b.ranges().is_empty(),
                    };
                    if empty {
                        return Some(c.span);
                    }
                }
            }
            None
        }
        Ast::Repetition(ref r) => find_empty_class(pattern, &r.ast, flags),
        Ast::Group(ref g) => {
            let mut inner = *flags;
            if let ast::GroupKind::NonCapturing(ref fl) = g.kind {
                apply_flags(&mut inner, fl);
            }
            find_empty_class(pattern, &g.ast, &mut inner)
        }
        Ast::Alternation(ref a) => {
            for x in a.asts.iter() {
                if let Some(s) = find_empty_class(pattern, x, flags) {
                    return Some(s);
                }
            }
            None
        }
        Ast::Concat(ref c) => {
            for x in c.asts.iter() {
                if let Some(s) = find_empty_class(pattern, x, flags) {
                    return Some(s);
                }
            }
            None
        }
        _ => None,
    }
}

/// Returns true if the old compiler would emit no instructions for `node`.
fn compiles_empty(node: &Ast) -> bool {
    match *node {
        Ast::Empty(_) | Ast::Flags(_) => true,
        Ast::Literal(_) | Ast::Dot(_) | Ast::Assertion(_) => false,
        Ast::ClassUnicode(_) | Ast::ClassPerl(_) | Ast::ClassBracketed(_) => false,
        Ast::Repetition(ref r) => match r.op.kind {
            ast::RepetitionKind::ZeroOrOne
            | ast::RepetitionKind::ZeroOrMore
            | ast::RepetitionKind::OneOrMore => false,
            ast::RepetitionKind::Range(ast::RepetitionRange::AtLeast(_)) => false,
            ast::RepetitionKind::Range(ast::RepetitionRange::Exactly(n)) => {
                n == 0 || compiles_empty(&r.ast)
            }
            ast::RepetitionKind::Range(ast::RepetitionRange::Bounded(m, n)) => {
                m == n && (m == 0 || compiles_empty(&r.ast))
            }
        },
        Ast::Group(ref g) => compiles_empty(&g.ast),
        Ast::Concat(ref c) => c.asts.iter().all(compiles_empty),
        Ast::Alternation(_) => false,
    }
}

fn has_empty_alternate(node: &Ast) -> bool {
    match *node {
        Ast::Alternation(ref a) => a
            .asts
            .iter()
            .any(|x| compiles_empty(x) || has_empty_alternate(x)),
        Ast::Repetition(ref r) => {
            let skipped = match r.op.kind {
                ast::RepetitionKind::Range(ast::RepetitionRange::Exactly(0)) => true,
                ast::RepetitionKind::Range(ast::RepetitionRange::Bounded(0, 0)) => true,
                _ => false,
            };
            !skipped && has_empty_alternate(&r.ast)
        }
        Ast::Group(ref g) => has_empty_alternate(&g.ast),
        Ast::Concat(ref c) => c.asts.iter().any(has_empty_alternate),
        _ => false,
    }
}

/// Formats a regex syntax error the way regex-syntax does.
fn format_error(pattern: &str, span: ast::Span, msg: &str) -> String {
    let mut line_count = pattern.lines().count();
    if pattern.ends_with('\n') {
        line_count += 1;
    }
    let lnw = if line_count <= 1 { 0 } else { line_count.to_string().len() };
    let mut notated = String::new();
    let one_line = span.start.line == span.end.line;
    for (i, line) in pattern.lines().enumerate() {
        if lnw > 0 {
            let n = (i + 1).to_string();
            for _ in 0..(lnw - n.len()) {
