            requires_quotes: rq,
            first_field_count: None,
            fields_written: 0,
            in_field: false,
            quoting: false,
            record_bytes: 0,
        }
    }

    fn should_quote(&self, field: &[u8]) -> bool {
        match self.opts.style {
            QuoteStyle::Always => true,
            QuoteStyle::Necessary => field.iter().any(|&b| self.requires_quotes[b as usize]),
        }
    }

    #[inline]
    fn avail(&self) -> usize {
        WBUF - self.buf.len()
    }

    /// Copies as much of `input` as fits. Returns (full, nin).
    #[inline]
    fn write_optimistic(&mut self, input: &[u8]) -> (bool, usize) {
        let n = std::cmp::min(input.len(), self.avail());
        self.buf.extend_from_slice(&input[..n]);
        self.record_bytes += n as u64;
        (input.len() > n, n)
    }

    /// Copies `input` only if all of it fits. Returns true if written.
    #[inline]
    fn write_pessimistic(&mut self, input: &[u8]) -> bool {
        if input.len() > self.avail() {
            false
        } else {
            self.buf.extend_from_slice(input);
            true
        }
    }

    /// Writes a quoted field's contents. Returns (full, nin).
    fn write_quoted(&mut self, mut input: &[u8]) -> (bool, usize) {
        let q = self.opts.quote;
        let mut nin = 0;
        loop {
            match input.iter().position(|&b| b == q) {
                None => {
                    let (full, i) = self.write_optimistic(input);
                    return (full, nin + i);
                }
                Some(next_quote) => {
                    let (full, i) = self.write_optimistic(&input[..next_quote]);
                    input = &input[i..];
                    nin += i;
                    if full {
                        return (true, nin);
                    }
                    let pair = if self.opts.double_quote { [q, q] } else { [self.opts.escape, q] };
                    if !self.write_pessimistic(&pair) {
                        return (true, nin);
                    }
                    self.record_bytes += 2;
                    nin += 1;
                    input = &input[1..];
                }
            }
        }
    }

    /// Core field writer. Returns (full, nin).
    fn core_field(&mut self, input: &[u8]) -> (bool, usize) {
        if !self.in_field {
            self.quoting = self.should_quote(input);
            if self.quoting {
                if !self.write_pessimistic(&[self.opts.quote]) {
                    return (true, 0);
                }
                self.record_bytes += 1;
            }
            self.in_field = true;
        }
        if self.quoting {
            self.write_quoted(input)
        } else {
            self.write_optimistic(input)
        }
    }

    /// Core delimiter writer. Returns true if complete.
    fn core_delimiter(&mut self) -> bool {
        if self.quoting {
            if !self.write_pessimistic(&[self.opts.quote]) {
                return false;
            }
            self.record_bytes += 1;
            self.quoting = false;
        }
        if !self.write_pessimistic(&[self.opts.delimiter]) {
            return false;
        }
        self.record_bytes += 1;
        self.in_field = false;
        true
    }

    /// Core terminator writer. Returns true if complete.
    fn core_terminator(&mut self) -> bool {
        if self.record_bytes == 0 {
            let q = self.opts.quote;
            if !self.write_pessimistic(&[q, q]) {
                return false;
            }
            self.record_bytes += 2;
        }
        if self.quoting {
            if !self.write_pessimistic(&[self.opts.quote]) {
                return false;
            }
            self.record_bytes += 1;
            self.quoting = false;
        }
        let ok = match self.opts.term {
            Terminator::Crlf => self.write_pessimistic(b"\r\n"),
            Terminator::Any(b) => self.write_pessimistic(&[b]),
        };
        if !ok {
            return false;
        }
        self.record_bytes = 0;
        self.in_field = false;
        true
    }

    pub fn write_field(&mut self, field: &[u8]) -> Result<()> {
        if self.fields_written > 0 {
            while !self.core_delimiter() {
                self.flush()?;
            }
        }
        let mut field = field;
        loop {
            let (full, nin) = self.core_field(field);
            field = &field[nin..];
            if !full {
                self.fields_written += 1;
                return Ok(());
            }
            self.flush()?;
        }
    }

    pub fn write_terminator(&mut self) -> Result<()> {
        if !self.opts.flexible {
            match self.first_field_count {
                None => self.first_field_count = Some(self.fields_written),
                Some(expected) => {
                    if expected != self.fields_written {
                        return Err(Error::UnequalLengths {
                            pos: None,
                            expected_len: expected,
                            len: self.fields_written,
                        });
                    }
                }
            }
        }
        while !self.core_terminator() {
            self.flush()?;
        }
        self.fields_written = 0;
        Ok(())
    }

    pub fn write_record<'a, I: IntoIterator<Item = &'a [u8]>>(&mut self, it: I) -> Result<()> {
        for f in it {
            self.write_field(f)?;
        }
        self.write_terminator()
    }

    pub fn write_byte_record(&mut self, r: &ByteRecord) -> Result<()> {
        self.write_record(r.iter())
    }

    fn flush_buf(&mut self) -> io::Result<()> {
        if !self.buf.is_empty() {
            let res = self.w.as_mut().unwrap().write_all(&self.buf);
            res?;
            self.buf.clear();
        }
        Ok(())
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.flush_buf()?;
        self.w.as_mut().unwrap().flush()?;
        Ok(())
    }
}

